// ===================== CONFIG (edit here only) =====================
const CONFIG = {
  brand: 'Dev SEO',                 // shown on reports and emails
  crawl_max_pages: 200,             // DataForSEO on-page crawl size (also used when reading crawled pages)
  crawl_js: false,                  // true = render JavaScript during the crawl (slower, costs more)
  qa_max_rounds: 2,                 // how many times the Editor may revise content that fails QA
  default_country: 'United States'
};

// DataForSEO location codes are 2000 + ISO-3166 numeric code
const COUNTRIES = {
  'United States':        { code: 2840, iso: 'US', lang: 'en', language: 'English', spelling: 'American English',   currency: 'USD' },
  'United Kingdom':       { code: 2826, iso: 'GB', lang: 'en', language: 'English', spelling: 'British English',    currency: 'GBP' },
  'Canada':               { code: 2124, iso: 'CA', lang: 'en', language: 'English', spelling: 'Canadian English',   currency: 'CAD' },
  'Australia':            { code: 2036, iso: 'AU', lang: 'en', language: 'English', spelling: 'Australian English', currency: 'AUD' },
  'New Zealand':          { code: 2554, iso: 'NZ', lang: 'en', language: 'English', spelling: 'British English',    currency: 'NZD' },
  'Ireland':              { code: 2372, iso: 'IE', lang: 'en', language: 'English', spelling: 'British English',    currency: 'EUR' },
  'Pakistan':             { code: 2586, iso: 'PK', lang: 'en', language: 'English', spelling: 'British English',    currency: 'PKR' },
  'India':                { code: 2356, iso: 'IN', lang: 'en', language: 'English', spelling: 'British English',    currency: 'INR' },
  'United Arab Emirates': { code: 2784, iso: 'AE', lang: 'en', language: 'English', spelling: 'British English',    currency: 'AED' },
  'Saudi Arabia':         { code: 2682, iso: 'SA', lang: 'en', language: 'English', spelling: 'British English',    currency: 'SAR' },
  'Singapore':            { code: 2702, iso: 'SG', lang: 'en', language: 'English', spelling: 'British English',    currency: 'SGD' },
  'South Africa':         { code: 2710, iso: 'ZA', lang: 'en', language: 'English', spelling: 'British English',    currency: 'ZAR' },
  'Germany':              { code: 2276, iso: 'DE', lang: 'de', language: 'German',  spelling: 'German',             currency: 'EUR' },
  'France':               { code: 2250, iso: 'FR', lang: 'fr', language: 'French',  spelling: 'French',             currency: 'EUR' },
  'Spain':                { code: 2724, iso: 'ES', lang: 'es', language: 'Spanish', spelling: 'European Spanish',   currency: 'EUR' },
  'Italy':                { code: 2380, iso: 'IT', lang: 'it', language: 'Italian', spelling: 'Italian',            currency: 'EUR' },
  'Netherlands':          { code: 2528, iso: 'NL', lang: 'nl', language: 'Dutch',   spelling: 'Dutch',              currency: 'EUR' },
  'Brazil':               { code: 2076, iso: 'BR', lang: 'pt', language: 'Portuguese', spelling: 'Brazilian Portuguese', currency: 'BRL' },
  'Mexico':               { code: 2484, iso: 'MX', lang: 'es', language: 'Spanish', spelling: 'Mexican Spanish',    currency: 'MXN' }
};
// ===================================================================

let p1, raw, via_webhook;
try {
  p1 = $('Start Form').first().json;
  raw = $input.first().json;
  via_webhook = false;
} catch (e) {
  // No Start Form in this execution -> triggered by the Webhook
  p1 = { 'What do you want?': 'I know my keyword' };
  raw = $input.first().json || {};
  via_webhook = true;
}
// n8n's Webhook node wraps the payload as { headers, params, query, body }
const p2 = (raw && raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) ? raw.body : (raw || {});

function pick(obj, ...words) {
  const key = Object.keys(obj || {}).find(k =>
    words.every(w => k.toLowerCase().replace(/[\s_-]+/g, ' ').includes(w))
  );
  return key ? obj[key] : '';
}
function asArray(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v) return v.split(/[,\n]/).map(s => s.trim()).filter(Boolean);
  return [];
}
function cleanDomain(v) {
  return String(v || '').trim().toLowerCase()
    .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '').replace(/:\d+$/, '');
}
// Public hostnames only: no IP literals, no localhost/internal names (SSRF guard)
const domainOk = (d) => {
  if (!d || d.length > 253) return false;
  if (/^(\d{1,3}\.){3}\d{1,3}$/.test(d)) return false;
  if (/^\[?[0-9a-f:]+\]?$/.test(d) && d.includes(':')) return false;
  if (/(^|\.)(localhost|local|internal|localdomain|home|lan|corp|intranet|test|example|invalid)$/.test(d)) return false;
  return /^([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(xn--[a-z0-9-]+|[a-z]{2,24})$/.test(d);
};

// ---------- Mode ----------
const choice = String(pick(p1, 'what', 'want') || '').toLowerCase();
let mode = 'discover';
let verdict_only = false;
if (choice.includes('check') && choice.includes('keyword')) { mode = 'keyword'; verdict_only = true; }
else if (choice.includes('know')) mode = 'keyword';
else if (choice.includes('describe')) mode = 'site_description';
else if (choice.includes('audit')) mode = 'audit';
if (via_webhook) {
  const m = String(p2.mode || '').toLowerCase();
  if (m === 'verdict' || m === 'check') { mode = 'keyword'; verdict_only = true; }
  else if (m === 'audit') mode = 'audit';
  else if (m === 'discover') mode = 'discover';
  else if (m === 'describe') mode = 'site_description';
}

// ---------- Country (name or ISO-2 code) ----------
const countryRaw = String(pick(p2, 'country') || '').trim();
let countryName = Object.keys(COUNTRIES).find(n => n.toLowerCase() === countryRaw.toLowerCase())
  || Object.keys(COUNTRIES).find(n => COUNTRIES[n].iso === countryRaw.toUpperCase())
  || (mode === 'site_description' ? CONFIG.default_country : '');
const c = COUNTRIES[countryName] || null;
if (mode !== 'site_description' && !c) throw new Error('Please select a Target Country.');

// ---------- Domain / email ----------
const domain = cleanDomain(pick(p2, 'domain') || pick(p2, 'website'));
if (domain && !domainOk(domain)) throw new Error('Please enter a public website address like example.com');

const email = String(pick(p2, 'email') || '').trim().toLowerCase();
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Please enter a valid email address.');

const callback_url = String(pick(p2, 'callback') || '').trim();
if (callback_url && !/^https:\/\/[^\s]+$/.test(callback_url)) throw new Error('callback_url must be an https URL.');

const competitors = asArray(pick(p2, 'competitor')).map(cleanDomain).filter(domainOk).filter(d => d !== domain).slice(0, 3);

// ---------- Other fields ----------
const features = asArray(pick(p2, 'feature')).map(f => String(f).toLowerCase());
const wants = asArray(pick(p2, 'receive')).map(w => String(w).toLowerCase());
const reportType = String(pick(p2, 'report type') || pick(p2, 'report_type') || '').toLowerCase();
const keyword  = String(pick(p2, 'keyword') || '').trim().toLowerCase().replace(/\s+/g, ' ');
const business = String(pick(p2, 'business') || '').trim();
const audience = String(pick(p2, 'customer') || pick(p2, 'audience') || '').trim();
const pageType = String(pick(p2, 'page', 'type') || '').trim() || 'Service Page';
let existing_page_url = String(pick(p2, 'existing') || '').trim();
if (existing_page_url && !/^https?:\/\//i.test(existing_page_url)) existing_page_url = 'https://' + existing_page_url.replace(/^\/+/, '');
if (existing_page_url && domain && cleanDomain(existing_page_url) !== domain) throw new Error('The existing page URL must be on ' + domain);

// ---------- What to produce ----------
let include_seo_report = false, include_content = false, include_audit = false, include_full_report = false;

if (mode === 'audit') {
  if (reportType.includes('full')) include_full_report = true; else include_audit = true;
} else if (mode === 'keyword' || mode === 'discover') {
  include_seo_report  = wants.some(w => w.includes('keyword report') || w.includes('seo report') || w === 'report');
  include_content     = wants.some(w => w.includes('content'));
  include_audit       = features.some(f => f.includes('site audit')) || wants.some(w => w.includes('site audit'));
  include_full_report = features.some(f => f.includes('full seo')) || wants.some(w => w.includes('full seo'));
  if (mode === 'keyword' && !verdict_only) {
    // "I know my keyword" always produces the page content; the keyword report is on by default too
    include_content = true;
    if (!wants.length) include_seo_report = true;
  }
}
if (include_full_report) include_audit = true;
if (verdict_only) { include_seo_report = false; include_content = false; include_audit = false; include_full_report = false; }

// ---------- Validation ----------
if (mode === 'keyword' && !keyword) throw new Error('Please enter a Target Keyword.');
if (mode === 'discover' && !business && !domain) throw new Error('Please describe your business OR enter your website domain.');
if ((mode === 'site_description' || mode === 'audit') && !domain) throw new Error('Website Domain is required.');
if (include_audit && !domain) throw new Error('Site Audit and Full SEO Report need your website domain.');
if (mode === 'audit' && !email) throw new Error('Email is required — the audit report is sent by email.');
if (mode === 'discover' && (include_content || include_seo_report || include_audit) && !email) {
  throw new Error('Please add your email — the extra reports you selected are sent by email.');
}
if (via_webhook && include_audit && !email) throw new Error('Audits requested via the API need an email address.');

const need_site_description =
  mode === 'site_description' ||
  (mode === 'discover' && !business) ||
  (mode === 'keyword' && !!domain && !business);

return [{
  json: {
    mode,
    keyword,
    business,
    audience,
    domain,
    email,
    competitors,
    page_type: pageType,
    existing_page_url,
    country: c ? countryName : null,
    country_iso: c ? c.iso : null,
    location_code: c ? c.code : null,
    language_code: c ? c.lang : 'en',
    language_name: c ? c.language : 'English',
    spelling: c ? c.spelling : 'American English',
    currency: c ? c.currency : null,
    include_seo_report,
    include_content,
    include_audit,
    include_full_report,
    verdict_only,
    audit_level: include_full_report ? 'full' : (include_audit ? 'site_audit' : null),
    need_site_description,
    via_webhook,
    callback_url,
    run_page_check: domain !== '' && (features.some(f => f.includes('page exists')) || !!existing_page_url),
    run_site_audit: include_audit,
    brand: CONFIG.brand,
    crawl_max_pages: CONFIG.crawl_max_pages,
    crawl_js: CONFIG.crawl_js,
    qa_max_rounds: CONFIG.qa_max_rounds,
    started_at: new Date().toISOString()
  }
}];

const input = $('Normalize Input').first().json;
let raw = String($input.first().json.site_text || '');

// Title nikal lo
const titleMatch = raw.match(/^Title:\s*(.+)$/m);
const pageTitle = titleMatch ? titleMatch[1].trim() : '';

let text = raw
  .replace(/^Title:.*$/m, '')
  .replace(/^URL Source:.*$/m, '')
  .replace(/^Markdown Content:\s*$/m, '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')        // images hatao
  .replace(/\[\s*\]\([^)]*\)/g, '')            // khaali links hatao
  .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')     // [text](url) → text
  .replace(/\*\*/g, '')                        // bold marks
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n\n')
  .trim()
  .slice(0, 12000);

// Site padhi gayi ya block hui?
const blocked = /access denied|forbidden|captcha|cloudflare|403|just a moment/i.test(text.slice(0, 500));
const read_ok = text.length > 200 && !blocked;

return [{
  json: {
    ...input,
    page_title: pageTitle,
    site_text: text,
    read_ok
  }
}];

// Accepts an object (from the Structured Output Parser) or a string with/without code fences or surrounding text
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  throw new Error('AI did not return valid JSON. Output was: ' + s.slice(0, 300));
};

const prev = $('Clean Site Text').first().json;
const desc = parseAgentJson($input.first().json.output);

return [{
  json: {
    ...prev,
    site_text: undefined,   // lamba text aage nahi chahiye
    site_description: desc,
    business: prev.business || desc.business_description,
    audience: prev.audience || (desc.target_audience || []).join(', ')
  }
}];

const d = $input.first().json;
const s = d.site_description || {};

const esc = (t) => String(t ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = (arr) => (arr || []).map(i => `<li>${esc(i)}</li>`).join('');
const tags = (arr) => (arr || []).map(i => `<span class="tag">${esc(i)}</span>`).join('');

const html = `
<style>
  .wrap{font-family:Arial,sans-serif;max-width:720px;margin:0 auto;color:#1e293b;text-align:left;line-height:1.6}
  h1{font-size:24px;margin:0 0 4px;color:#0f172a}
  .sub{color:#64748b;margin-bottom:20px}
  .card{background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:16px 18px;margin-bottom:14px}
  .card h2{font-size:15px;margin:0 0 8px;color:#1e3a8a;text-transform:uppercase;letter-spacing:.5px}
  ul{margin:0;padding-left:18px}
  .tag{display:inline-block;background:#e0e7ff;color:#1e3a8a;border-radius:20px;padding:4px 10px;margin:3px 4px 3px 0;font-size:13px}
  .meta{background:#fff;border:1px dashed #94a3b8;border-radius:8px;padding:10px;font-size:14px;margin-top:6px}
  .grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
  @media(max-width:600px){.grid{grid-template-columns:1fr}}
</style>
<div class="wrap">
  <h1>${esc(s.business_name || d.domain)}</h1>
  <div class="sub">${esc(s.one_line_summary)}</div>

  <div class="card">
    <h2>What Your Business Does</h2>
    <p>${esc(s.business_description)}</p>
  </div>

  <div class="grid">
    <div class="card"><h2>Products / Services</h2><ul>${list(s.products_or_services)}</ul></div>
    <div class="card"><h2>Target Audience</h2><ul>${list(s.target_audience)}</ul></div>
    <div class="card"><h2>Why Customers Choose You</h2><ul>${list(s.unique_selling_points)}</ul></div>
    <div class="card"><h2>Details</h2>
      <p><b>Industry:</b> ${esc(s.industry)}<br>
      <b>Serves:</b> ${esc(s.location_served)}<br>
      <b>Brand Tone:</b> ${esc(s.tone_of_brand)}</p>
    </div>
  </div>

  <div class="card">
    <h2>Suggested SEO Meta Tags</h2>
    <div class="meta"><b>Title:</b> ${esc(s.suggested_meta_title)}</div>
    <div class="meta"><b>Description:</b> ${esc(s.suggested_meta_description)}</div>
  </div>

  <div class="card">
    <h2>Keywords Customers Might Search</h2>
    ${tags(s.seed_keywords)}
  </div>
</div>`;

return [{ json: { ...d, result_html: html } }];

const res = $input.first().json || {};
const task = res.tasks?.[0] || {};
const items = task.result?.[0]?.items || [];

let base;
try { base = $('Hand Off To Keyword').first().json; }
catch (e) { base = $('Route Mode').first().json; }
const ours = String(base.domain || '').toLowerCase().replace(/^www\./, '');

const SKIP = [
  // social, video, forums
  'youtube.com', 'wikipedia.org', 'reddit.com', 'quora.com', 'facebook.com', 'instagram.com', 'linkedin.com',
  'pinterest.com', 'tiktok.com', 'x.com', 'twitter.com', 'medium.com',
  // marketplaces, app stores
  'amazon.com', 'amazon.ae', 'daraz.pk', 'noon.com', 'play.google.com', 'apps.apple.com',
  // job boards
  'indeed.com', 'glassdoor.com', 'bayt.com', 'naukrigulf.com', 'rozee.pk', 'monster.com',
  // training, courses
  'udemy.com', 'coursera.org', 'euro-training.net', 'simplilearn.com',
  // software vendors' own product and docs pages (not service competitors)
  'microsoft.com', 'dynamics.com', 'sap.com', 'oracle.com', 'salesforce.com', 'google.com'
];
const isSkipped = (d) => SKIP.some(s => d === s || d.endsWith('.' + s));

const cleanUrl = (u) => {
  try {
    const x = new URL(u);
    ['srsltid', 'utm_source', 'utm_medium', 'utm_campaign', 'gclid', 'fbclid'].forEach(p => x.searchParams.delete(p));
    return x.toString();
  } catch (e) { return u; }
};

const seen = new Set();
const picked = [];
const skipped = [];

for (const it of items) {
  if (it.type !== 'organic' || !it.url) continue;
  const d = String(it.domain || '').toLowerCase().replace(/^www\./, '');
  if (!d) continue;
  if (ours && (d === ours || d.endsWith('.' + ours))) { skipped.push(d + ' (your site)'); continue; }
  if (isSkipped(d)) { skipped.push(d); continue; }
  if (seen.has(d)) continue;
  seen.add(d);
  picked.push({
    rank: it.rank_group,
    url: cleanUrl(it.url),
    domain: d,
    title: it.title || '',
    snippet: it.description || ''
  });
  if (picked.length >= 8) break;
}

if (!picked.length) {
  return [{
    json: {
      rank: null, url: null, domain: null, title: null, snippet: null,
      no_competitors: true,
      serp_status: task.status_message || res.status_message || 'no results',
      serp_results: items.length,
      skipped
    }
  }];
}

return picked.map(p => ({ json: { ...p, no_competitors: false } }));

const input = $('Collect Site URLs').first().json;
const meta = $('Pick Top 6').all();
const pages = $input.all();

const competitors = [];
const failed = [];

const stripMd = (s) => String(s || '')
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
  .replace(/\[\s*\]\([^)]*\)/g, '')
  .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
  .replace(/https?:\/\/\S+/g, '')
  .replace(/[*_`]+/g, '')
  .replace(/[ \t]+/g, ' ')
  .trim();

const junk = /cookie|consent|privacy|opt[- ]?out|personal (data|information)|gdpr|advertising|storage related|targeted|all rights reserved|copyright|©|trademark|terms (&|and) conditions|opens in a new (tab|window)|follow us|sign in|sign up|log in|register for free|create an account|password|download the app|lost network connectivity|javascript|browser settings|newsletter|subscribe|view all|happy to accept|save my preferences|^description |^duration /i;

pages.forEach((p, i) => {
  const j = p.json || {};
  const info = meta[i]?.json || {};
  const raw = String(j.page_text || j.data || j.body || '');

  if (j.error || !raw) {
    failed.push({ url: info.url, reason: j.error ? (j.error.message || JSON.stringify(j.error)).slice(0, 150) : 'Empty response' });
    return;
  }

  const lines = raw.replace(/^(Title|URL Source|Markdown Content|Published Time):.*$/gm, '').split('\n');

  const headings = [...new Set(
    lines
      .filter(l => /^#{1,3}\s/.test(l.trim()))
      .map(l => {
        const level = l.trim().match(/^#+/)[0].length;
        return 'H' + level + ': ' + stripMd(l.replace(/^#+\s*/, ''));
      })
      .filter(h => h.length > 5 && !junk.test(h))
  )].slice(0, 30);

  const seenLines = new Set();
  const body = lines
    .map(l => l.trim())
    .filter(l => {
      const isHeading = /^#{1,6}\s/.test(l);
      const clean = stripMd(l.replace(/^[*\-•]\s*/, '').replace(/^#+\s*/, ''));
      if (!clean || junk.test(clean)) return false;
      if (!isHeading && clean.split(/\s+/).length < 6) return false;
      const key = clean.toLowerCase();
      if (seenLines.has(key)) return false;
      seenLines.add(key);
      return true;
    })
    .map(l => /^#{1,6}\s/.test(l)
      ? '\n## ' + stripMd(l.replace(/^#+\s*/, ''))
      : stripMd(l.replace(/^[*\-•]\s*/, '')))
    .join('\n')
    .replace(/(\n## [^\n]+)(?=\n## |\s*$)/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const blocked = /captcha|cloudflare ray id|access denied|just a moment/i.test(raw.slice(0, 800));
  const words = body.split(/\s+/).filter(Boolean).length;

  if (blocked || words < 80) {
    failed.push({ url: info.url, reason: blocked ? 'Blocked by CAPTCHA / bot protection' : `Too little text (${words} words)` });
    return;
  }

  competitors.push({
    rank: info.rank, url: info.url, domain: info.domain, title: info.title, snippet: info.snippet,
    word_count: words, headings, content: body.slice(0, 4500)
  });
});

competitors.splice(6);

const avg = competitors.length
  ? Math.round(competitors.reduce((s, c) => s + c.word_count, 0) / competitors.length)
  : 1500;

// ---------- SERP features (from the same SERP call) ----------
let serpItems = [];
let seCount = null;
try {
  const res = $('SERP Top 10').first().json.tasks?.[0]?.result?.[0] || {};
  serpItems = res.items || [];
  seCount = res.se_results_count ?? null;
} catch (e) { serpItems = []; }

const norm = (d) => String(d || '').toLowerCase().replace(/^www\./, '');
const paa = [];
const related = [];
let featured = null;
let aio = null;
const featureTypes = new Set();
for (const it of serpItems) {
  featureTypes.add(it.type);
  if (it.type === 'people_also_ask') {
    (it.items || []).forEach(q => { const t = q.title || q.question || ''; if (t && !paa.includes(t)) paa.push(t); });
  } else if (it.type === 'related_searches') {
    (it.items || []).forEach(q => { const t = typeof q === 'string' ? q : (q.title || q.keyword || ''); if (t && !related.includes(t)) related.push(t); });
  } else if (it.type === 'featured_snippet' && !featured) {
    featured = { domain: norm(it.domain), title: it.title || '', text: String(it.description || it.text || '').slice(0, 400), url: it.url || '' };
  } else if (it.type === 'ai_overview' && !aio) {
    const texts = [];
    (it.items || []).forEach(x => { if (x.text) texts.push(x.text); if (x.title) texts.push(x.title); });
    const refs = [];
    (it.references || []).forEach(r => refs.push(norm(r.domain || String(r.url || '').replace(/^https?:\/\//, '').split('/')[0])));
    (it.items || []).forEach(x => (x.references || []).forEach(r => refs.push(norm(r.domain || String(r.url || '').replace(/^https?:\/\//, '').split('/')[0]))));
    aio = { present: true, text: texts.join(' ').slice(0, 800), cited_domains: [...new Set(refs.filter(Boolean))].slice(0, 12) };
  }
}
const serp_features = {
  se_results_count: seCount,
  people_also_ask: paa.slice(0, 12),
  related_searches: related.slice(0, 10),
  featured_snippet: featured,
  ai_overview: aio || { present: false, text: '', cited_domains: [] },
  features_present: [...featureTypes].filter(t => t !== 'organic'),
  video_results: featureTypes.has('video'),
  shopping_results: featureTypes.has('shopping') || featureTypes.has('popular_products'),
  local_pack: featureTypes.has('local_pack') || featureTypes.has('map')
};

const digest = competitors.map(c => `
=== COMPETITOR #${c.rank}: ${c.domain} ===
URL: ${c.url}
Title: ${c.title}
Meta Description: ${c.snippet}
Useful Word Count: ${c.word_count}
Headings:
${c.headings.join('\n')}

Content Excerpt:
${c.content}
`).join('\n');

const serpDigest = [
  featured ? `FEATURED SNIPPET (held by ${featured.domain}): "${featured.text}"` : 'FEATURED SNIPPET: none',
  serp_features.ai_overview.present ? `AI OVERVIEW: present, cites ${serp_features.ai_overview.cited_domains.join(', ') || 'unknown sources'}. Summary: ${serp_features.ai_overview.text.slice(0, 500)}` : 'AI OVERVIEW: not shown for this query',
  paa.length ? 'PEOPLE ALSO ASK:\n- ' + paa.slice(0, 12).join('\n- ') : 'PEOPLE ALSO ASK: none',
  related.length ? 'RELATED SEARCHES: ' + related.slice(0, 10).join(' | ') : '',
  'OTHER SERP FEATURES: ' + (serp_features.features_present.join(', ') || 'none')
].filter(Boolean).join('\n');

return [{
  json: {
    ...input,
    competitors,
    competitors_read: competitors.length,
    avg_competitor_words: avg,
    failed_pages: failed,
    competitor_digest: digest,
    serp_features,
    serp_digest: serpDigest
  }
}];

// Accepts an object (from the Structured Output Parser) or a string with/without code fences or surrounding text
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  throw new Error('AI did not return valid JSON. Output was: ' + s.slice(0, 300));
};

const prev = $('Clean Competitor Pages').first().json;
const analysis = parseAgentJson($input.first().json.output);

return [{
  json: {
    ...prev,
    competitor_digest: undefined,
    competitor_analysis: analysis
  }
}];

const prev = $('Parse Analysis').first().json;
const res = $input.first().json || {};
const item = res.tasks?.[0]?.result?.[0]?.items?.[0] || null;

const info = item?.keyword_info || {};
const props = item?.keyword_properties || {};
const intent = item?.search_intent_info || {};
const links = item?.avg_backlinks_info || {};
const trend = info.search_volume_trend || {};

// Difficulty ko aam alfaaz mein
const kd = props.keyword_difficulty;
const kdLabel = kd == null ? 'Unknown'
  : kd < 30 ? 'Easy'
  : kd < 50 ? 'Medium'
  : kd < 70 ? 'Hard'
  : 'Very Hard';

const keyword_data = item ? {
  search_volume: info.search_volume ?? null,
  cpc: info.cpc ?? null,
  ads_competition: info.competition_level ?? null,
  keyword_difficulty: kd ?? null,
  difficulty_label: kdLabel,
  google_intent: intent.main_intent ?? null,
  trend_yearly_pct: trend.yearly ?? null,
  trend_quarterly_pct: trend.quarterly ?? null,
  monthly_trend: (info.monthly_searches || [])
    .slice(0, 12)
    .map(m => ({ month: `${m.year}-${String(m.month).padStart(2, '0')}`, searches: m.search_volume })),
  competitor_backlink_strength: {
    avg_referring_domains: links.referring_domains != null ? Math.round(links.referring_domains) : null,
    avg_backlinks: links.backlinks != null ? Math.round(links.backlinks) : null,
    avg_dofollow: links.dofollow != null ? Math.round(links.dofollow) : null
  }
} : {
  note: 'Keyword data not available for this keyword/country'
};

// Competitors ka lamba content aage AI ko nahi chahiye, sirf summary
const competitors_summary = (prev.competitors || []).map(c => ({
  rank: c.rank,
  domain: c.domain,
  url: c.url,
  title: c.title,
  word_count: c.word_count,
  headings: c.headings
}));

return [{
  json: {
    ...prev,
    competitors: undefined,
    competitors_summary,
    keyword_data
  }
}];

