parameters.jsCode:
// Accepts an object (from the Structured Output Parser) or a string with/without code fences or surrounding text
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  throw new Error('AI did not return valid JSON. Output was: ' + s.slice(0, 300));
};

const prev = $('Parse Verdict').first().json;   // includes verdict + keyword data + site context
const brief = parseAgentJson($input.first().json.output);

// Word count check
const totalWords = (brief.outline || []).reduce((s, sec) => s + (Number(sec.target_words) || 0), 0);

return [{
  json: {
    ...prev,
    content_brief: brief,
    brief_outline_words: totalWords
  }
}];

const prev = $('Parse Brief').first().json;
const rawOut = $input.first().json.output;
let md = (typeof rawOut === 'string' ? rawOut : JSON.stringify(rawOut || '')).trim();
const round = ($runIndex || 0) + 1;
const fixes = [];
const warnings = [];
const brief = prev.content_brief || {};
const kw = String(prev.keyword || '').toLowerCase();
const domain = prev.domain || '';
const today = new Date().toISOString().slice(0, 10);

const plain = (s) => String(s || '')
  .replace(/\[([^\[\]]+)\]\([^)]*\)/g, '$1')
  .replace(/[*_`>]+/g, '')
  .replace(/\s+/g, ' ')
  .trim();
const countWords = (t) => String(t || '').split(/\s+/).filter(Boolean).length;
const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// 1. Strip any schema/script the model added (schema is generated deterministically below)
const before0 = md;
md = md.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/```(?:json|html)?\s*\{[\s\S]*?"@context"[\s\S]*?```/gi, '').trim();
if (md !== before0) fixes.push('Removed model-written schema/script blocks (schema is generated by the QA step)');

// 2. The word "placeholder" must never appear
const before1 = md;
md = md
  .replace(/\s*\((placeholders?|placeholder for [^)]*)\)/gi, '')
  .replace(/\b(indicative\s+)?price placeholders?\b/gi, 'prices')
  .replace(/\bplaceholders?\b/gi, 'details');
if (md !== before1) fixes.push('Removed the word "placeholder" from text');

// 3. No business details given -> invented prices become [Price]
if (!prev.business) {
  const sym = { GBP: '£', USD: '\\$', CAD: '\\$', AUD: '\\$', NZD: '\\$', SGD: '\\$', PKR: '(?:Rs\\.?|PKR)', INR: '(?:Rs\\.?|₹|INR)', AED: '(?:AED|Dh)', SAR: '(?:SAR|SR)', EUR: '€', ZAR: 'R', BRL: 'R\\$', MXN: '\\$' }[prev.currency] || '[£$€]';
  const priceRe = new RegExp(sym + '\\s?\\d[\\d.,]*(\\s?(–|-|to)\\s?' + sym + '?\\s?\\d[\\d.,]*)?', 'g');
  const count = (md.match(priceRe) || []).length;
  if (count) { md = md.replace(priceRe, '[Price]'); fixes.push(`Replaced ${count} invented price(s) with [Price]`); }
}

// 4. Meta lines
const metaOf = (label) => { const m = md.match(new RegExp('^' + label + ':\\s*(.+)$', 'im')); return m ? m[1].trim() : ''; };
const metaTitle = metaOf('Title');
const metaDesc = metaOf('Meta Description');
const slug = metaOf('Slug');

// 5. Internal links: only real pages on the user's site may be linked
const allowed = new Set();
const normUrl = (u) => String(u || '').trim().replace(/\/$/, '').toLowerCase();
(prev.internal_link_candidates || []).forEach(c => allowed.add(normUrl(c.url)));
(prev.site_urls || []).forEach(u => allowed.add(normUrl(u)));
if (prev.existing_page && prev.existing_page.url) allowed.add(normUrl(prev.existing_page.url));
if (domain) allowed.add(normUrl('https://' + domain));
const removedLinks = [];
let internalLinks = 0, externalLinks = 0;
md = md.replace(/\[([^\[\]]+)\]\(([^)\s]+)\)/g, (m, text, url) => {
  let u = url.trim();
  const isRelative = u.startsWith('/');
  if (isRelative) u = domain ? 'https://' + domain + u : u;
  const host = u.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#]/)[0].toLowerCase();
  const internal = !!domain && (host === domain || host.endsWith('.' + domain));
  if (internal || isRelative) {
    if (allowed.size && allowed.has(normUrl(u))) { internalLinks++; return '[' + text + '](' + u + ')'; }
    removedLinks.push(u);
    return text;
  }
  externalLinks++;
  return m;
});
if (removedLinks.length) fixes.push(`Removed ${removedLinks.length} link(s) to pages that do not exist on ${domain || 'the site'}: ` + removedLinks.slice(0, 4).join(', '));

// 6. FAQs
const faqs = [];
let cur = null, inAnswer = false;
for (const raw of md.split('\n')) {
  const l = raw.trim();
  let m;
  if ((m = l.match(/^\**Q\d+[:.]\**\s*(.+)$/))) { cur = { q: m[1].replace(/\*+$/, '').trim(), a: '' }; faqs.push(cur); inAnswer = false; continue; }
  if ((m = l.match(/^\**A\d+[:.]\**\s*(.*)$/)) && cur) { cur.a = m[1]; inAnswer = true; continue; }
  if (inAnswer && l && !l.startsWith('#')) { cur.a += ' ' + l; continue; }
  if (!l || l.startsWith('#')) inAnswer = false;
}
const validFaqs = faqs.filter(f => f.q && f.a && countWords(f.a) >= 15);

// 7. Sections
const body = md;
const withoutMeta = body.replace(/^(Title|Meta Description|Slug|Primary Keyword|Secondary Keywords):.*$/gm, '');
const faqStart = withoutMeta.search(/^## (Frequently Asked Questions|FAQs?)/im);
const afterFaq = faqStart >= 0 ? withoutMeta.slice(faqStart + 5).search(/^## /m) : -1;
const faqPart = faqStart >= 0 ? withoutMeta.slice(faqStart, afterFaq >= 0 ? faqStart + 5 + afterFaq : undefined) : '';
const mainPart = withoutMeta.replace(faqPart, '');
const totalWords = countWords(withoutMeta);
const mainWords = countWords(mainPart);
const faqWords = countWords(faqPart);

const h1 = (body.match(/^# .+$/m) || [''])[0];
const h2s = body.match(/^## .+$/gm) || [];
const faqHeadings = h2s.filter(h => /faq|frequently asked/i.test(h)).length;
const lastH2 = h2s[h2s.length - 1] || '';

// Quick answer block (for featured snippets / AI answers)
const qaMatch = withoutMeta.match(/^\**\s*Quick answer:?\**\s*(.+)$/im);
const answerWords = qaMatch ? countWords(plain(qaMatch[1])) : 0;

// 8. Keyword checks
const kwRe = kw ? new RegExp('\\b' + escRe(kw) + '\\b', 'g') : null;
const kwCount = kwRe ? (withoutMeta.toLowerCase().match(kwRe) || []).length : 0;
const density = totalWords ? +(kwCount * kw.split(/\s+/).length / totalWords * 100).toFixed(2) : 0;
const first100 = plain(mainPart.replace(/^#.*$/gm, '')).split(/\s+/).slice(0, 100).join(' ').toLowerCase();

// 9. Unverified statistics (numbers that need a source or a placeholder)
const noBrackets = withoutMeta.replace(/\[[^\]]*\]/g, '').replace(/\|[^\n]*\|/g, '');
const statHits = new Set();
for (const m of noBrackets.matchAll(/\b\d[\d,.]*\s?%/g)) statHits.add(m[0].trim());
for (const m of noBrackets.matchAll(/\b(over|more than|up to|nearly|around|approximately|about)\s+\d[\d,.]*\+?(\s?%|\s+\w+)?/gi)) statHits.add(m[0].trim());
for (const m of noBrackets.matchAll(/\b\d[\d,.]*\+\s+(years?|clients?|customers?|projects?|users?|students?|universities|schools|companies|installations?|reviews?|countries|awards?)\b/gi)) statHits.add(m[0].trim());
const stats = [...statHits].filter(s => !/^(19|20)\d\d/.test(s)).slice(0, 8);

// 10. Warnings
const target = brief.target_word_count || 800;
if (mainWords < target * 0.8) warnings.push(`Main content is short: ${mainWords} words vs target ${target}`);
if (mainWords > target * 1.5) warnings.push(`Main content is much longer than target: ${mainWords} words vs ${target}`);
if (!metaTitle) warnings.push('Meta title line missing');
else {
  if (metaTitle.length > 60) warnings.push(`Meta title is ${metaTitle.length} characters (max 60)`);
  if (metaTitle.length < 30) warnings.push(`Meta title is only ${metaTitle.length} characters (aim for 50-60)`);
  if (kw && !metaTitle.toLowerCase().includes(kw)) warnings.push('Primary keyword missing from the meta title');
}
if (!metaDesc) warnings.push('Meta description line missing');
else {
  if (metaDesc.length > 155) warnings.push(`Meta description is ${metaDesc.length} characters (max 155)`);
  if (metaDesc.length < 70) warnings.push(`Meta description is only ${metaDesc.length} characters (aim for 120-155)`);
}
if (slug && !/^\/?[a-z0-9]+(-[a-z0-9]+)*\/?$/.test(slug)) warnings.push('Slug should be lowercase words joined by hyphens');
if (!h1) warnings.push('H1 missing');
else if (kw && !h1.toLowerCase().includes(kw)) warnings.push('Primary keyword missing from H1');
if (kw && !first100.includes(kw)) warnings.push('Primary keyword not in the first 100 words');
if (kwCount < 3) warnings.push(`Primary keyword used only ${kwCount} time(s)`);
if (density > 2.5) warnings.push(`Keyword density is high (${density}%) — risk of keyword stuffing`);
if (h2s.length < 4) warnings.push(`Only ${h2s.length} H2 sections (brief expects ${(brief.outline || []).length || 'more'})`);
if (!qaMatch) warnings.push('Quick answer block missing (a 40-70 word direct answer right after the introduction)');
else if (answerWords < 35 || answerWords > 90) warnings.push(`Quick answer is ${answerWords} words (aim for 40-70)`);
if (validFaqs.length < 5) warnings.push(`Only ${validFaqs.length} complete FAQs found (need 5+, answers 40-70 words)`);
if (faqHeadings > 1) warnings.push('Duplicate FAQ sections found');
if (/faq|frequently asked/i.test(lastH2)) warnings.push('CTA section should come after the FAQs');
if (!/\|.*\|/.test(body)) warnings.push('Comparison table missing');
if (/guarantee/i.test(body) && !prev.business) warnings.push('Contains a guarantee claim — please verify');
if (stats.length) warnings.push('Unverified statistics that need a source or a [Statistic] marker: ' + stats.join('; '));
if ((prev.internal_link_candidates || []).length > 1 && internalLinks === 0) warnings.push('No internal links to existing pages on the site');

// 11. Schema (deterministic, page-type aware)
const bizName = (prev.site_description && prev.site_description.business_name) ? String(prev.site_description.business_name).trim() : '';
const biz = bizName || '[Your Business Name]';
const pageUrl = (prev.existing_page && prev.existing_page.url) || (domain ? 'https://' + domain + '/' + String(slug || '').replace(/^\/|\/$/g, '') : '[Page URL]');
const h1Text = plain(h1.replace(/^#\s*/, '')) || metaTitle;
const org = { '@type': 'Organization', name: biz, url: domain ? 'https://' + domain + '/' : '[Website URL]' };
const blocks = [];
const pt = String(prev.page_type || '').toLowerCase();
if (pt.includes('blog')) {
  blocks.push({ type: 'Article', json: { '@context': 'https://schema.org', '@type': 'Article', headline: h1Text, description: plain(metaDesc), author: { '@type': 'Person', name: '[Author Name]', url: '[Author Page URL]' }, publisher: org, datePublished: today, dateModified: today, mainEntityOfPage: { '@type': 'WebPage', '@id': pageUrl }, keywords: [prev.keyword, ...(brief.secondary_keywords || []).slice(0, 5)].filter(Boolean).join(', ') } });
} else if (pt.includes('product')) {
  blocks.push({ type: 'Product', json: { '@context': 'https://schema.org', '@type': 'Product', name: h1Text, description: plain(metaDesc), brand: { '@type': 'Brand', name: biz }, url: pageUrl, offers: { '@type': 'Offer', priceCurrency: prev.currency || 'USD', price: '[Price as a number]', availability: 'https://schema.org/InStock', url: pageUrl } } });
} else {
  blocks.push({ type: 'Service', json: { '@context': 'https://schema.org', '@type': 'Service', name: h1Text, serviceType: prev.keyword, description: plain(metaDesc), provider: org, areaServed: prev.country || '[Country]', url: pageUrl } });
}
blocks.push({ type: 'BreadcrumbList', json: { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [
  { '@type': 'ListItem', position: 1, name: 'Home', item: domain ? 'https://' + domain + '/' : '[Website URL]' },
  { '@type': 'ListItem', position: 2, name: h1Text, item: pageUrl }
] } });
if (validFaqs.length) {
  blocks.push({ type: 'FAQPage', note: 'Google stopped showing FAQ rich results in May 2026; keep for other engines and AI assistants, or drop it.', json: { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: validFaqs.map(f => ({ '@type': 'Question', name: plain(f.q), acceptedAnswer: { '@type': 'Answer', text: plain(f.a) } })) } });
}
fixes.push('Generated ' + blocks.map(b => b.type).join(' + ') + ' schema');

return [{
  json: {
    ...prev,
    output: md,
    qa_round: round,
    meta: { title: metaTitle, description: metaDesc, slug },
    schema_blocks: blocks,
    content_qa: {
      round,
      total_words: totalWords,
      main_content_words: mainWords,
      faq_words: faqWords,
      target_word_count: target,
      keyword_mentions: kwCount,
      keyword_density_pct: density,
      h2_count: h2s.length,
      faq_count: validFaqs.length,
      internal_links: internalLinks,
      external_links: externalLinks,
      answer_block_words: answerWords,
      meta_title_length: metaTitle.length,
      meta_description_length: metaDesc.length,
      unverified_statistics: stats,
      schema_types: blocks.map(b => b.type),
      auto_fixes: fixes,
      warnings,
      passed: warnings.length === 0
    }
  }
}];

const d = $input.first().json;
const md = String(d.output || '');
const kd = d.keyword_data || {};
const ca = d.competitor_analysis || {};
const qa = d.content_qa || {};
const brief = d.content_brief || {};

const wantSeo = d.include_seo_report !== false;
const wantContent = !!d.include_content && md.length > 0;
const wantAudit = !!d.include_audit;
const wantVerdict = !!d.verdict;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = (n) => (n == null || n === '' ? 'N/A' : Number(n).toLocaleString('en-GB'));

let secNo = 0;
const h2 = (title, pageBreak) => '<h2' + (pageBreak ? ' class="pb"' : '') + '>' + (++secNo) + '. ' + esc(title) + '</h2>';

// Schema comes from the QA step (deterministic, page-type aware)
const scriptRe = new RegExp('<' + 'script type="application/ld\\+json">([\\s\\S]*?)<' + '/script>', 'gi');
const schemaBlocks = Array.isArray(d.schema_blocks) ? d.schema_blocks : [];
let content = md.replace(scriptRe, '').trim();
const sf = d.serp_features || null;

// Meta lines alag karo
const metaRe = /^(Title|Meta Description|Slug|Primary Keyword|Secondary Keywords):\s*(.+)$/gim;
const meta = [];
let m;
while ((m = metaRe.exec(content)) !== null) meta.push({ label: m[1], value: m[2] });
content = content.replace(metaRe, '').trim();

function inline(s) {
  let t = esc(s);
  t = t.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  t = t.replace(/\[([^\[\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
  t = t.replace(/\[([^\[\]]+)\](?!\()/g, '<span class="ph">[$1]</span>');
  return t;
}

function mdToHtml(text) {
  const out = [];
  let list = null, table = null;
  const closeList = () => { if (list) { out.push('</' + list + '>'); list = null; } };
  const closeTable = () => { if (table) { out.push('</table>'); table = null; } };
  for (const raw of text.split('\n')) {
    const l = raw.trim();
    if (l.startsWith('|')) {
      closeList();
      if (/^\|[\s:|-]+\|$/.test(l)) continue;
      const cells = l.replace(/^\||\|$/g, '').split('|').map(c => c.trim());
      if (!table) { out.push('<table class="ct">'); table = 'open';
        out.push('<tr>' + cells.map(c => '<th>' + inline(c) + '</th>').join('') + '</tr>'); }
      else out.push('<tr>' + cells.map(c => '<td>' + inline(c) + '</td>').join('') + '</tr>');
      continue;
    }
    closeTable();
    if (!l) { closeList(); continue; }
    let x;
    if ((x = l.match(/^(#{1,4})\s+(.+)$/))) { closeList(); const h = x[1].length; out.push('<h' + h + '>' + inline(x[2]) + '</h' + h + '>'); continue; }
    if ((x = l.match(/^>\s*(.+)$/))) { closeList(); out.push('<div class="callout">' + inline(x[1].replace(/^Note:\s*/i, '')) + '</div>'); continue; }
    if ((x = l.match(/^Q\d+:\s*(.+)$/))) { closeList(); out.push('<p class="fq">' + inline(x[1]) + '</p>'); continue; }
    if ((x = l.match(/^A\d+:\s*(.+)$/))) { closeList(); out.push('<p class="fa">' + inline(x[1]) + '</p>'); continue; }
    if ((x = l.match(/^[-*]\s+(.+)$/))) { if (list !== 'ul') { closeList(); out.push('<ul>'); list = 'ul'; } out.push('<li>' + inline(x[1]) + '</li>'); continue; }
    if ((x = l.match(/^\d+\.\s+(.+)$/))) { if (list !== 'ol') { closeList(); out.push('<ol>'); list = 'ol'; } out.push('<li>' + inline(x[1]) + '</li>'); continue; }
    closeList();
    out.push('<p>' + inline(l) + '</p>');
  }
  closeList(); closeTable();
  return out.join('\n');
}

