    .filter(d => !d.endsWith(domain) && !IGNORE_EXT.test(d)))];

  P.push({
    url: pk.url, kind: pk.kind, status: r.statusCode || 0, html, text, nodes, types, invalid,
    h1s, headings, imgs, tels, extDomains,
    forms: (html.match(/<form\b/gi) || []).length,
    inputs: (html.match(/<(input|textarea)\b/gi) || []).length,
    lang: (html.match(/<html[^>]*\slang=["']([^"']+)["']/i) || [])[1] || null,
    hreflang: /hreflang=/i.test(html),
    hreflangs: [...html.matchAll(/<link[^>]+hreflang=["']([^"']+)["'][^>]*>/gi)].map(m => ({ lang: m[1].toLowerCase(), href: (m[0].match(/href=["']([^"']+)["']/i) || [])[1] || '' })),
    speculation: /type=["']speculationrules["']/i.test(html),
    viewport: /<meta[^>]+name=["']viewport["']/i.test(html),
    noindex: /<meta[^>]+name=["']robots["'][^>]+content=["'][^"']*noindex/i.test(html) || /<meta[^>]+content=["'][^"']*noindex[^"']*["'][^>]+name=["']robots["']/i.test(html),
    mixed: [...html.matchAll(/<(?:img|script|link|iframe|source|video|audio)\b[^>]*\s(?:src|href)=["']http:\/\/[^"']+["']/gi)].length,
    canonical: (html.match(/<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']+)["']/i) || html.match(/<link[^>]+href=["']([^"']+)["'][^>]*rel=["']canonical["']/i) || [])[1] || null
  });
});

const findings = [];
const works = [];
const urlsToCheck = [];
const F = (category, severity, title, evidence, why, fix, sample_urls = [], affected = null, total = null) => findings.push({
  category, severity, title, evidence, why, fix, sample_urls,
  affected_count: affected, affected_pct: affected != null && total ? Math.round(affected / total * 100) : 100,
  scope: affected != null ? 'page' : 'site'
});

const home = P.find(p => p.kind === 'home') || P[0] || { nodes: [], types: [], h1s: [], imgs: [], text: '', html: '' };
const allNodes = P.flatMap(p => p.nodes);
const ORG_TYPES = /^(Organization|Corporation|LocalBusiness|ProfessionalService|Store|Restaurant|MedicalBusiness|LegalService|FinancialService|EducationalOrganization)$/;
const org = home.nodes.find(n => typesOf(n).some(t => ORG_TYPES.test(t))) || allNodes.find(n => typesOf(n).some(t => ORG_TYPES.test(t)));

// ---------- Schema basics ----------
const invalidTotal = P.reduce((s, p) => s + p.invalid, 0);
if (invalidTotal) F('Schema', 'High', 'Invalid structured data (JSON-LD will not parse)', invalidTotal + ' broken JSON-LD block(s) on sampled pages', 'Search engines ignore structured data that cannot be parsed.', 'Validate the markup with Google Rich Results Test and fix syntax errors.', P.filter(p => p.invalid).map(p => p.url));
if (!home.nodes.length) {
  F('Schema', 'High', 'No structured data on the homepage', 'No JSON-LD found on ' + home.url, 'Structured data helps Google and AI systems understand who you are and what you offer.', 'Add Organization (or LocalBusiness/ProfessionalService) JSON-LD with name, logo, address, contact details and sameAs profiles.');
} else works.push('Structured data present on the homepage (' + home.types.join(', ') + ')');

if (!org) {
  F('Schema', 'High', 'No Organization schema', 'None of ' + P.length + ' sampled pages declare Organization or LocalBusiness', 'Without it, search engines and AI tools have no machine-readable identity for the business.', 'Add Organization JSON-LD sitewide with @id, name, logo, address, telephone, email and sameAs.');
} else {
  works.push('Organization schema found (' + typesOf(org).join(', ') + ')');

  // logo
  const logo = urlOf(org.logo);
  if (!logo) F('Schema', 'Medium', 'Organization schema has no logo', 'logo property missing', 'Google uses the schema logo for knowledge panels and brand results.', 'Add a logo ImageObject with url, width and height.');
  else urlsToCheck.push({ url: logo, purpose: 'Organization logo' });
  if (urlOf(org.image)) urlsToCheck.push({ url: urlOf(org.image), purpose: 'Organization image' });

  // sameAs
  const sameAs = asArr(org.sameAs).map(String);
  const bad = sameAs.filter(u => {
    const m = u.match(/(?:twitter|x)\.com\/([^\/?#]+)/i);
    return m ? !/^[A-Za-z0-9_]{1,15}$/.test(m[1]) : !/^https?:\/\/[^\s]+\.[^\s]+/.test(u);
  });
  if (bad.length) F('Schema', 'High', 'Malformed sameAs profile link', 'Invalid: ' + bad.join(', '), 'A broken identity link is worse than none: it confuses entity matching in Google and AI systems.', 'Remove or correct the invalid entry and link only real, active profiles.');
  if (sameAs.length - bad.length < 3) F('Schema', 'Medium', 'Few verified profiles linked in sameAs', (sameAs.length - bad.length) + ' valid sameAs link(s): ' + (sameAs.join(', ') || 'none'), 'Entity recognition works best with 4-6 independent profiles (LinkedIn, directories, Wikidata, Crunchbase, review sites).', 'Add sameAs links to every real business profile.');
  else works.push(sameAs.length + ' sameAs profile links');

  // NAP
  const addr = org.address && typeof org.address === 'object' ? org.address : null;
  const missing = [];
  if (!addr || !addr.streetAddress) missing.push('streetAddress');
  if (!addr || !addr.addressLocality) missing.push('addressLocality');
  const cps = asArr(org.contactPoint);
  const hasTel = org.telephone || cps.some(c => c.telephone);
  const hasEmail = org.email || cps.some(c => c.email);
  const visibleTel = P.some(p => p.tels.length) || /\+\d[\d\s-]{7,}/.test(home.text);
  const visibleMail = /[\w.+-]+@[\w-]+\.[\w.]+/.test(P.map(p => p.text).join(' '));
  if (!hasTel && visibleTel) missing.push('telephone');
  if (!hasEmail && visibleMail) missing.push('email');
  if (missing.length) F('Schema', 'High', 'Structured contact details are thinner than what the site shows', 'Missing in schema: ' + missing.join(', '), 'Search engines cannot match your business listing to your site when the address and phone in schema are incomplete.', 'Add full PostalAddress (streetAddress, addressLocality, addressRegion, postalCode, addressCountry), telephone and email to Organization schema.');
  else works.push('Organization schema includes full address and contact details');
  if (!org.alternateName) F('Schema', 'Low', 'No alternateName in Organization schema', 'alternateName missing', 'Helps search engines and AI map spelling variants of the brand to one entity.', 'Add alternateName with common variants of the brand name.');
  if (!org['@id']) F('Schema', 'Low', 'Organization schema has no @id', '@id missing', 'An @id lets other schema (Service, Article) reference the same organisation cleanly.', 'Add "@id": "https://' + domain + '/#organization".');

  // founding date vs experience claims
  const fy = parseInt(String(org.foundingDate || '').slice(0, 4), 10);
  const claims = P.flatMap(p => [...p.text.matchAll(/(\d{1,2})\s*\+?\s*years?\b/gi)].map(m => ({ n: +m[1], url: p.url })));
  const maxClaim = claims.reduce((a, c) => c.n > a.n ? c : a, { n: 0 });
  if (fy && maxClaim.n && maxClaim.n > (nowYear - fy) + 1) {
    F('Content', 'High', 'Experience claim conflicts with the founding date', '"' + maxClaim.n + '+ years" on ' + maxClaim.url + ' but schema foundingDate is ' + org.foundingDate, 'Contradictory facts damage trust with buyers and with search quality systems.', 'Make the claims consistent (e.g. "leadership with ' + maxClaim.n + '+ years of experience") or correct the founding date.', [maxClaim.url]);
  }

  // language
  const langs = asArr(org.availableLanguage).length;
  if (langs > 1 && !P.some(p => p.hreflang)) F('Technical', 'Info', 'Multiple languages declared but no hreflang', 'Schema lists ' + langs + ' languages; no hreflang tags found', 'Only matters once other language versions exist.', 'Add hreflang when translated pages go live.');
}

// ---------- Service & Breadcrumb ----------
const services = P.filter(p => p.kind === 'service');
const noService = services.filter(p => !p.types.some(t => /Service|Product|Offer/i.test(t)));
if (services.length && noService.length) F('Schema', noService.length === services.length ? 'High' : 'Medium', 'Service pages have no Service schema', noService.length + ' of ' + services.length + ' sampled service pages', 'Service schema tells search engines exactly what you offer, where and by whom, and separates similar service pages.', 'Add Service JSON-LD (serviceType, provider → Organization @id, areaServed) on each service page.', noService.map(p => p.url), noService.length, services.length);
else if (services.length) works.push('Service schema present on sampled service pages');

const inner = P.filter(p => p.kind !== 'home');
const noCrumb = inner.filter(p => !p.types.includes('BreadcrumbList'));
if (inner.length && noCrumb.length) F('Schema', noCrumb.length === inner.length ? 'High' : 'Medium', 'No BreadcrumbList schema', noCrumb.length + ' of ' + inner.length + ' sampled inner pages', 'Breadcrumbs show site hierarchy in search results and help search engines understand structure.', 'Add BreadcrumbList JSON-LD to every inner page.', noCrumb.map(p => p.url), noCrumb.length, inner.length);
else if (inner.length) works.push('BreadcrumbList schema present');

// ---------- Articles ----------
const arts = P.filter(p => p.kind === 'article');
const artNodes = arts.map(p => ({ p, n: p.nodes.find(n => typesOf(n).some(t => /Article|BlogPosting|NewsArticle/.test(t))) }));
const noAuthor = artNodes.filter(({ n }) => {
  const a = n && asArr(n.author)[0];
  const name = a && (typeof a === 'string' ? a : a.name);
  const isOrg = a && typesOf(a).some(t => /Organization/.test(t));
  return !name || isOrg || /team|staff|admin|editor/i.test(name);
});
if (arts.length && noAuthor.length) F('Content', 'High', 'Articles have no named human author', noAuthor.length + ' of ' + arts.length + ' sampled articles', 'Expertise signals (E-E-A-T) depend on a real, credentialed author, especially on advice or compliance topics.', 'Credit a named expert with an author page, job title and LinkedIn (author @type Person with url and sameAs).', noAuthor.map(x => x.p.url), noAuthor.length, arts.length);
const frozen = artNodes.filter(({ n }) => n && n.datePublished && n.dateModified && n.datePublished === n.dateModified);
if (frozen.length) F('Content', 'Medium', 'No freshness signal on articles', frozen.length + ' of ' + arts.length + ' sampled articles have dateModified equal to datePublished', 'Time-sensitive content looks unmaintained without a genuine update date.', 'Show a visible "Last reviewed" date and update dateModified only after real edits.', frozen.map(x => x.p.url), frozen.length, arts.length);
artNodes.forEach(({ n }) => { const pl = n && n.publisher && urlOf(n.publisher.logo); if (pl) urlsToCheck.push({ url: pl, purpose: 'Article publisher logo' }); });
const noCite = arts.filter(p => p.extDomains.length === 0);
if (arts.length && noCite.length) F('Content', noCite.length === arts.length ? 'High' : 'Medium', 'Articles cite no external sources', noCite.length + ' of ' + arts.length + ' sampled articles link to no authoritative source', 'Uncited facts are less trustworthy and less likely to be quoted by Google AI Overviews, ChatGPT or Perplexity.', 'Link each key fact, law or statistic to its primary source (government, standards body, vendor docs).', noCite.map(p => p.url), noCite.length, arts.length);
else if (arts.length) works.push('Sampled articles link to external sources');

// ---------- Homepage H1 ----------
const brand = String((org && org.name) || domain.split('.')[0]).toLowerCase().replace(/[^a-z0-9]/g, '');
const h1 = home.h1s[0] || '';
if (h1 && brand && !h1.toLowerCase().replace(/[^a-z0-9]/g, '').includes(brand.slice(0, Math.max(4, brand.length - 1)))) {
  F('On-Page', 'Low', 'Homepage H1 does not name the business or what it does', 'Homepage H1: "' + h1 + '"', 'The homepage H1 is the strongest on-page signal of who you are, what you sell and where.', 'Rewrite the H1 to name the brand, the service category and the location.', [home.url]);
}

// ---------- Contact form ----------
const contact = P.find(p => p.kind === 'contact');
if (contact && contact.forms === 0 && contact.inputs === 0) F('Technical', 'Medium', 'Contact form is not in the server-rendered HTML', 'Raw HTML of ' + contact.url + ' has 0 <form> and 0 <input> elements', 'Crawlers and AI agents that do not run JavaScript see no way to contact you.', 'Server-render the form (fields, labels, submit) or add a <noscript> fallback form.', [contact.url]);

// ---------- Images ----------
const heroImg = home.imgs[0];
if (heroImg && !(attr(heroImg, 'alt') || '').trim()) F('Images', 'Medium', 'Main homepage image has empty alt text', 'First image on the homepage: ' + (attr(heroImg, 'src') || '').slice(0, 80), 'The main image is usually the LCP element and carries meaning; empty alt loses context for search and accessibility.', 'Write descriptive alt text for the hero image.', [home.url]);
const noDim = P.flatMap(p => p.imgs.filter(t => !attr(t, 'width') || !attr(t, 'height')).map(t => ({ url: p.url, src: attr(t, 'src') })));
if (noDim.length >= 3) F('Images', 'Medium', 'Images without width and height', noDim.length + ' images on sampled pages lack explicit dimensions', 'Images without reserved space can shift the layout while loading (CLS).', 'Add width and height (or aspect-ratio) to every image.', [...new Set(noDim.map(x => x.url))]);

// ---------- Phone numbers ----------
const hiddenTels = [];
P.forEach(p => p.tels.forEach(t => { const digits = t.replace(/\D/g, '').slice(-7); if (digits && !p.text.replace(/\D/g, '').includes(digits)) hiddenTels.push(t + ' (' + p.url + ')'); }));
if (hiddenTels.length) F('Content', 'Low', 'Phone number in a link but not shown on the page', [...new Set(hiddenTels)].slice(0, 5).join('; '), 'Hidden or unlabeled numbers can be picked up by directories and AI as conflicting contact details.', 'Confirm the number, display it, or remove the link.');

// ---------- Content defects ----------
const latex = P.filter(p => /\$\\(ge|le|geq|leq|lt|gt|times)\$|\$[<>]\$/.test(p.text));
if (latex.length) F('Content', 'Medium', 'Raw formatting code visible on the page (LaTeX)', latex.length + ' page(s) show symbols like $\\ge$', 'Visible code looks unprofessional and breaks the most quotable passages.', 'Replace with plain characters such as ≥, ≤, <, >.', latex.map(p => p.url));
const artifacts = P.filter(p => p.headings.some(h => /^h[1-6]\s*:/i.test(h)));
if (artifacts.length) F('Content', 'Medium', 'Authoring artifacts in headings', 'Headings start with "H4:" or similar on ' + artifacts.length + ' page(s)', 'Leftover drafting labels show in the page, table of contents and anchor links.', 'Remove the "H2:/H3:/H4:" prefixes from headings.', artifacts.map(p => p.url));

// ---------- Mobile, indexability, security, hreflang ----------
const noViewport = P.filter(p => p.status === 200 && p.html.length > 500 && !p.viewport);
if (noViewport.length) F('Technical', 'High', 'Missing viewport meta tag (mobile-first indexing)', noViewport.length + ' of ' + P.length + ' sampled pages have no <meta name="viewport">', 'Without a viewport tag the page is not mobile-friendly and Google indexes the mobile version first.', 'Add <meta name="viewport" content="width=device-width, initial-scale=1"> to the template.', noViewport.map(p => p.url), noViewport.length, P.length);
const noindexed = P.filter(p => p.noindex);
if (noindexed.length) F('Crawlability & Indexing', noindexed.some(p => p.kind === 'home' || p.kind === 'service') ? 'Critical' : 'Medium', 'Key pages carry a noindex tag', noindexed.map(p => p.kind + ': ' + p.url).join('; '), 'A noindex tag removes the page from Google entirely, however good it is.', 'Remove the noindex directive from pages that should rank; keep it only on utility pages.', noindexed.map(p => p.url), noindexed.length, P.length);
const mixedPages = P.filter(p => p.mixed > 0);
if (mixedPages.length) F('Security', 'Medium', 'Mixed content (HTTP resources on HTTPS pages)', mixedPages.reduce((s, p) => s + p.mixed, 0) + ' http:// resources referenced on ' + mixedPages.length + ' sampled pages', 'Browsers block or warn about insecure resources, which can break layout and scripts and undermines trust.', 'Reference every image, script and stylesheet over https://.', mixedPages.map(p => p.url), mixedPages.length, P.length);
const withHreflang = P.filter(p => p.hreflangs.length);
if (withHreflang.length) {
  const problems = [];
  withHreflang.forEach(p => {
    const langs = p.hreflangs.map(x => x.lang);
    if (!langs.includes('x-default')) problems.push(p.url + ': no x-default');
    const self = p.hreflangs.some(x => String(x.href).replace(/\/$/, '') === String(p.url).replace(/\/$/, ''));
    if (!self) problems.push(p.url + ': no self-referencing hreflang');
    langs.forEach(l => { if (l !== 'x-default' && !/^[a-z]{2,3}(-[a-z0-9]{2,4})?$/i.test(l)) problems.push(p.url + ': invalid code ' + l); });
  });
  if (problems.length) F('Technical', 'Medium', 'hreflang annotations are incomplete', problems.slice(0, 6).join('; '), 'Incomplete hreflang sets are ignored by Google, so the wrong language version can rank in each country.', 'Every language version must list all versions including itself, plus an x-default.', [...new Set(problems.map(x => x.split(':')[0]))]);
  else works.push('hreflang annotations look complete on sampled pages');
}
const absCanon = (p) => { let c = String(p.canonical || ''); if (c.startsWith('/')) c = 'https://' + domain + c; return c.replace(/\/$/, '').toLowerCase().replace(/^https?:\/\/(www\.)?/, ''); };
const canonMismatch = P.filter(p => p.canonical && p.status === 200 && (p.kind === 'home' || p.kind === 'service') && absCanon(p) !== String(p.url).replace(/\/$/, '').toLowerCase().replace(/^https?:\/\/(www\.)?/, ''));
if (canonMismatch.length) F('Crawlability & Indexing', 'Info', 'Key pages canonicalise to a different URL', canonMismatch.map(p => p.url + ' → ' + p.canonical).slice(0, 5).join('; '), 'Fine if intentional, but these pages will not rank on their own URL.', 'Confirm each canonical is intended.', canonMismatch.map(p => p.url));

// ---------- Misc ----------
if (!home.lang) F('Technical', 'Low', 'No language declared on the page', '<html> has no lang attribute', 'Helps browsers and search engines pick the right language.', 'Add lang="en" (or the correct language) to the <html> tag.');
if (!P.some(p => p.speculation)) F('Performance', 'Low', 'No speculation rules for instant navigation', 'No <script type="speculationrules"> found', 'Prefetching likely next pages makes navigation feel instant.', 'Add conservative speculation rules for key pages (e.g. contact and top services).');

return [{
  json: {
    ...base,
    html_analysis: {
      sampled_pages: P.map(p => ({ url: p.url, kind: p.kind, status: p.status, schema_types: p.types })),
      findings, works, urls_to_check: urlsToCheck
    }
  }
}];

const d = $input.first().json;
const list = d.html_analysis.urls_to_check || [];
const seen = new Set();
const out = [];
for (const u of list) {
  let url = u.url;
  if (url && url.startsWith('/')) url = 'https://' + d.domain + url;
  if (!url || seen.has(url)) continue;
  seen.add(url);
  out.push({ json: { url, purpose: u.purpose } });
}
if (!out.length) out.push({ json: { url: 'https://' + d.domain + '/', purpose: 'none' } });
return out;

const d = $('Analyze HTML').first().json;
const a = d.html_analysis;
const urls = $('URLs To Check').all().map(i => i.json);
const res = $input.all().map(i => i.json);

const findings = [...a.findings];
const works = [...a.works];

urls.forEach((u, i) => {
  if (u.purpose === 'none') return;
  const status = (res[i] || {}).statusCode || 0;
  if (!status || status >= 400) {
    const isLogo = /logo/i.test(u.purpose);
    findings.push({
      category: 'Schema', severity: isLogo ? 'Critical' : 'Medium',
      title: u.purpose + ' URL is broken',
      evidence: u.url + ' returned ' + (status || 'no response'),
      why: isLogo ? 'A broken schema logo breaks Google logo and organisation rich results, and is usually repeated on every page from one template.' : 'Search engines cannot use images that do not load.',
      fix: 'Point the schema to a working image URL (ImageObject with width and height). Verify: the URL should return 200.',
      sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site'
    });
  } else {
    works.push(u.purpose + ' loads correctly (' + status + ')');
  }
});

return [{
  json: {
    ...d,
    extra_findings: [...(d.extra_findings || []), ...findings],
    extra_works: [...(d.extra_works || []), ...works]
  }
}];

const base = $('Schema Findings').first().json;
const ours = base.domain;
const labsItems = $('Find Competitors').first().json.tasks?.[0]?.result?.[0]?.items || [];
const queries = $('Fallback Queries').all().map(i => i.json.query);
const serps = $input.all().map(i => i.json);

const BIG = ['microsoft.com', 'google.com', 'youtube.com', 'linkedin.com', 'facebook.com', 'wikipedia.org',
  'amazon.com', 'apple.com', 'reddit.com', 'quora.com', 'medium.com', 'instagram.com', 'twitter.com', 'x.com',
  'pinterest.com', 'tiktok.com', 'github.com', 'indeed.com', 'glassdoor.com', 'forbes.com', 'clutch.co', 'g2.com',
  'goodfirms.co', 'capterra.com', 'trustpilot.com', 'crunchbase.com', 'yelp.com', 'upwork.com', 'fiverr.com',
  'sortlist.com', 'designrush.com', 'gartner.com', 'techradar.com', 'bayut.com', 'dubizzle.com', 'yellowpages.ae'];
const isBig = (d) => BIG.some(b => d === b || d.endsWith('.' + b)) || /\.(gov|edu)(\.|$)/.test(d);
const clean = (d) => String(d || '').toLowerCase().replace(/^www\./, '');
const isOurs = (d) => d === ours || d.endsWith('.' + ours);

const manual = (base.competitors || []).map(clean).filter(d => d && !isOurs(d));
let comps = [];
let method = '';

if (manual.length) {
  comps = manual.slice(0, 3).map(d => ({ domain: d, shared: null, source: 'provided' }));
  method = 'provided by user';
} else {
  const score = {};
  const shared = {};
  labsItems.forEach(it => {
    const d = clean(it.domain);
    if (!d || isOurs(d) || isBig(d)) return;
    score[d] = (score[d] || 0) + (it.intersections || 0) * 10;
    shared[d] = it.intersections ?? null;
  });
  serps.forEach(s => {
    const items = s.tasks?.[0]?.result?.[0]?.items || [];
    items.filter(x => x.type === 'organic' && x.rank_group <= 10).forEach(x => {
      const d = clean(x.domain);
      if (!d || isOurs(d) || isBig(d)) return;
      score[d] = (score[d] || 0) + (11 - x.rank_group);
    });
  });
  comps = Object.entries(score).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([d]) => ({ domain: d, shared: shared[d] ?? null, source: 'auto' }));
  method = labsItems.length ? 'auto-detected from shared rankings and Google results for: ' + queries.join(', ')
    : 'auto-detected from Google results for: ' + queries.join(', ');
}

return [
  { json: { domain: ours, is_you: true, shared: null, source: 'you', method } },
  ...comps.map(c => ({ json: { ...c, is_you: false, method } }))
];

const base = $('Schema Findings').first().json;
const list = $('Pick Competitors').all().map(i => i.json);
const ov = $('Domain Overview').all().map(i => i.json);
const ages = $input.all().map(i => i.json);

const rows = list.map((c, i) => {
  const m = ov[i]?.tasks?.[0]?.result?.[0]?.items?.[0]?.metrics?.organic || {};
  const top3 = (m.pos_1 || 0) + (m.pos_2_3 || 0);
  const top10 = top3 + (m.pos_4_10 || 0);
  const w = ages[i]?.tasks?.[0]?.result?.[0]?.items?.[0] || null;
  const rdap = (ages[i]?.events || []).find(e => /registration/i.test(e.eventAction || ''));
  const regRaw = (w && (w.created_datetime || w.created_date)) || (rdap && rdap.eventDate) || null;
  const reg = regRaw ? String(regRaw).slice(0, 10) : null;
  const age = reg ? Number(((Date.now() - new Date(reg)) / 31557600000).toFixed(1)) : null;
  return {
    domain: c.domain,
    is_you: !!c.is_you,
    shared_keywords: c.shared,
    organic_keywords: m.count ?? 0,
    top3, top10,
    est_monthly_traffic: m.etv != null ? Math.round(m.etv) : 0,
    traffic_value_usd: m.estimated_paid_traffic_cost != null ? Math.round(m.estimated_paid_traffic_cost) : 0,
    registered: reg,
    domain_age_years: age
  };
});

const you = rows.find(r => r.is_you) || {};
const comps = rows.filter(r => !r.is_you);
const median = (arr) => { const a = arr.filter(v => v != null).sort((x, y) => x - y); if (!a.length) return null; const m = Math.floor(a.length / 2); return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2; };
const med = {
  organic_keywords: median(comps.map(c => c.organic_keywords)),
  top10: median(comps.map(c => c.top10)),
  est_monthly_traffic: median(comps.map(c => c.est_monthly_traffic)),
  domain_age_years: median(comps.map(c => c.domain_age_years))
};

const findings = [];
const works = [];
const F = (severity, title, evidence, why, fix) => findings.push({
  category: 'Authority', severity, title, evidence, why, fix,
  sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site'
});
const names = comps.map(c => c.domain).join(', ');

if ((you.top10 || 0) === 0) {
  F('Critical', 'The site does not rank in Google’s top 10 for any keyword',
    'Top-10 rankings in ' + (base.country || 'the target country') + ': ' + base.domain + ' 0' + (comps.length ? ' vs competitor median ' + (med.top10 ?? 'N/A') + ' (' + names + ')' : ''),
    'Without top-10 rankings the site gets almost no organic traffic, however good the pages are.',
    'Build authority first (partner listings, directories, reviews, mentions) and target long-tail keywords where competitors are weak.');
} else if (med.top10 && you.top10 < med.top10 * 0.25) {
  F('High', 'Far fewer top-10 rankings than competitors', base.domain + ' ' + you.top10 + ' vs competitor median ' + med.top10,
    'Competitors are visible for many more searches.', 'Use the keyword gap to target terms competitors rank for, starting with low-difficulty ones.');
} else if (comps.length) {
  works.push('Top-10 rankings comparable with competitors (' + you.top10 + ' vs median ' + med.top10 + ')');
}

if (comps.length && med.est_monthly_traffic && (you.est_monthly_traffic || 0) < med.est_monthly_traffic * 0.1) {
  F('High', 'Organic traffic is under 10% of competitors',
    'Estimated monthly organic visits: ' + base.domain + ' ' + (you.est_monthly_traffic || 0) + ' vs competitor median ' + Math.round(med.est_monthly_traffic),
    'Most searchers in this market are going to competitors.', 'Close the keyword and backlink gaps shown in this report.');
}

if (you.domain_age_years != null && you.domain_age_years < 1) {
  F('High', 'Very young domain' + (med.domain_age_years ? ' competing with long-established sites' : ''),
    base.domain + ' registered ' + you.registered + ' (' + you.domain_age_years + ' years)' + (med.domain_age_years != null ? ' vs competitor median ' + med.domain_age_years + ' years' : ''),
    'New domains have little accumulated trust; on-page fixes alone rarely move competitive terms in the first year.',
    'Invest in off-site entity building (partner directories, reviews, mentions) and target long-tail, lower-difficulty searches first.');
}

if (!comps.length) {
  F('Info', 'No competitors could be identified', 'No overlapping domains found for ' + base.country,
    'Competitor comparisons in this report are limited.', 'Add up to 3 competitors in the form for a full comparison.');
}

return [{
  json: {
    ...base,
    competitor_benchmark: {
      country: base.country,
      source: (list[0] && list[0].method) || '',
      rows,
      medians: med
    },
    extra_findings: [...(base.extra_findings || []), ...findings],
    extra_works: [...(base.extra_works || []), ...works]
  }
}];

const base = $('Competitor Analysis').first().json;
const targets = $('KW Targets').all().map(i => i.json);
const ranked = $('Ranked Keywords').all().map(i => i.json);
const ideasRes = $input.first().json || {};
const seeds = $('Fallback Queries').all().map(i => i.json.query).filter(Boolean);
const INTENTS = ['informational', 'navigational', 'commercial', 'transactional'];
const brand = base.domain.split('.')[0].toLowerCase();

// Intent: DataForSEO ka ho to wahi, warna alfaaz se andaza
const classify = (kw, intent) => {
  if (INTENTS.includes(intent)) return intent;
  const k = String(kw).toLowerCase();
  if (k.includes(brand)) return 'navigational';
  if (/\b(price|pricing|cost|costs|buy|hire|quote|near me|licen[cs]e|subscription|free trial|demo)\b/.test(k)) return 'transactional';
  if (/\b(best|top|vs|versus|compare|comparison|review|reviews|alternatives?|services?|company|companies|agency|partner|partners|consultants?|consulting|providers?|firms?)\b/.test(k)) return 'commercial';
  return 'informational';
};

// ---------- Ranked keywords (aap + competitors) ----------
const byDomain = targets.map((t, i) => {
  const items = ranked[i]?.tasks?.[0]?.result?.[0]?.items || [];
  const kws = items.map(it => {
    const kd = it.keyword_data || {};
    const info = kd.keyword_info || {};
    const se = (it.ranked_serp_element || {}).serp_item || {};
    const kw = String(kd.keyword || '').toLowerCase();
    return {
      keyword: kw,
      volume: info.search_volume ?? 0,
      cpc: info.cpc ?? null,
      difficulty: (kd.keyword_properties || {}).keyword_difficulty ?? null,
      intent: classify(kw, (kd.search_intent_info || {}).main_intent),
      position: se.rank_group ?? null,
      url: se.url || null
    };
  }).filter(k => k.keyword);
  const by_intent = {};
  INTENTS.forEach(x => by_intent[x] = kws.filter(k => k.intent === x).length);
  return {
    domain: t.domain, is_you: t.is_you,
    total: kws.length,
    top3: kws.filter(k => k.position && k.position <= 3).length,
    top10: kws.filter(k => k.position && k.position <= 10).length,
    by_intent, keywords: kws
  };
});

const you = byDomain.find(d => d.is_you) || { keywords: [], by_intent: {}, total: 0, top10: 0 };
const comps = byDomain.filter(d => !d.is_you);
const median = (arr) => { const a = arr.filter(v => v != null).sort((x, y) => x - y); if (!a.length) return null; const m = Math.floor(a.length / 2); return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2; };

// Competitor rankings ka map: keyword -> [{domain, position}]
const compRank = {};
comps.forEach(c => c.keywords.forEach(k => {
  if (!k.position || k.position > 10) return;
  (compRank[k.keyword] = compRank[k.keyword] || []).push({ domain: c.domain, position: k.position });
}));
const yourPos = {};
you.keywords.forEach(k => { yourPos[k.keyword] = k.position; });

// ---------- Aapke top keywords har intent mein ----------
const your_top_by_intent = {};
INTENTS.forEach(x => {
  your_top_by_intent[x] = you.keywords.filter(k => k.intent === x)
    .sort((a, b) => (b.volume || 0) - (a.volume || 0)).slice(0, 8);
});

// ---------- Keyword opportunities (4 intents) ----------
const ideaItems = ideasRes.tasks?.[0]?.result?.[0]?.items || [];
const seen = new Set();
const ideas = [];
ideaItems.forEach(it => {
  const kd = it.keyword_data || it;
  const kw = String(kd.keyword || '').toLowerCase().trim();
  if (!kw || seen.has(kw)) return;
  seen.add(kw);
  const info = kd.keyword_info || {};
  const vol = info.search_volume ?? 0;
  if (!vol) return;
  ideas.push({
    keyword: kw,
    volume: vol,
    difficulty: (kd.keyword_properties || {}).keyword_difficulty ?? null,
    cpc: info.cpc ?? null,
    intent: classify(kw, (kd.search_intent_info || {}).main_intent),
    your_position: yourPos[kw] ?? null,
    competitors: compRank[kw] || []
  });
});
// Competitors ke keywords bhi opportunities mein (jo ideas mein na hon)
Object.entries(compRank).forEach(([kw, list]) => {
  if (seen.has(kw)) return;
  const src = comps.flatMap(c => c.keywords).find(k => k.keyword === kw) || {};
  seen.add(kw);
  ideas.push({ keyword: kw, volume: src.volume || 0, difficulty: src.difficulty ?? null, cpc: src.cpc ?? null, intent: src.intent || classify(kw), your_position: yourPos[kw] ?? null, competitors: list });
});

const notWinning = ideas.filter(k => !k.your_position || k.your_position > 10);
const opportunities_by_intent = {};
INTENTS.forEach(x => {
  opportunities_by_intent[x] = notWinning.filter(k => k.intent === x)
    .sort((a, b) => (b.volume || 0) - (a.volume || 0)).slice(0, 10);
});
const easy_wins = notWinning
  .filter(k => k.difficulty != null && k.difficulty < 30 && k.volume >= 20)
  .sort((a, b) => (b.volume || 0) - (a.volume || 0)).slice(0, 10);

// ---------- Keyword gap ----------
const keyword_gap = notWinning.filter(k => k.competitors.length && (!k.your_position || k.your_position > 20))
  .sort((a, b) => b.competitors.length - a.competitors.length || (b.volume || 0) - (a.volume || 0))
  .slice(0, 25);

// ---------- Page 1 ke qareeb ----------
const striking_distance = you.keywords.filter(k => k.position >= 11 && k.position <= 20)
  .sort((a, b) => (b.volume || 0) - (a.volume || 0)).slice(0, 10);

// ---------- Findings ----------
const findings = [];
const works = [];
const F = (severity, title, evidence, why, fix) => findings.push({
  category: 'Authority', severity, title, evidence, why, fix,
  sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site'
});

if (keyword_gap.length) {
  F('High', 'Keyword gap: searches competitors win and you do not',
    keyword_gap.length + ' keywords where competitors rank in the top 10 and you are not in the top 20. Top: ' +
    keyword_gap.slice(0, 5).map(g => '"' + g.keyword + '" (' + (g.volume || 0) + '/mo)').join(', '),
    'Each of these is proven demand in your market that is currently going to competitors.',
    'Create or improve a dedicated page for the highest-volume, lowest-difficulty gap keywords first.');
}
INTENTS.forEach(x => {
  const med = median(comps.map(c => c.by_intent[x]));
  if ((you.by_intent[x] || 0) === 0 && med != null && med >= 5) {
    F('Medium', 'No rankings for ' + x + ' searches',
      'You rank for 0 ' + x + ' keywords vs competitor median ' + med,
      'You are missing a whole stage of the buyer journey that competitors capture.',
      x === 'informational' ? 'Publish helpful guides that answer the questions buyers research.' :
      x === 'commercial' ? 'Add comparison, "best", pricing and service-selection pages.' :
      x === 'transactional' ? 'Strengthen service and contact pages around buy/hire/quote searches.' :
      'Make sure branded searches lead clearly to your site.');
  }
});
if (easy_wins.length) {
  F('Low', 'Low-difficulty keywords you can target now',
    easy_wins.slice(0, 5).map(k => '"' + k.keyword + '" (' + k.volume + '/mo, difficulty ' + k.difficulty + ')').join(', '),
    'These searches have real demand and weak competition, the best starting point for a young site.',
    'Build or optimise one focused page per keyword group, starting with the highest volume.');
}
if (striking_distance.length) {
  F('Low', 'Keywords close to page 1 (positions 11-20)',
    striking_distance.slice(0, 5).map(k => '"' + k.keyword + '" #' + k.position).join(', '),
    'These are the fastest wins: small improvements can move them onto page 1.',
    'Improve the ranking page (depth, internal links, title) for each of these keywords.');
}
if (you.top10 > 0) works.push('Ranks in the Google top 10 for ' + you.top10 + ' keywords');

return [{
  json: {
    ...base,
    site_keywords: {
      seeds,
      domains: byDomain.map(d => ({ domain: d.domain, is_you: d.is_you, total: d.total, top3: d.top3, top10: d.top10, by_intent: d.by_intent })),
      your_top_by_intent,
      opportunities_by_intent,
      easy_wins,
      keyword_gap,
      striking_distance
    },
    extra_findings: [...(base.extra_findings || []), ...findings],
    extra_works: [...(base.extra_works || []), ...works]
  }
}];

const base = $('Analyze Keywords').first().json;
const targets = $('BL Targets').all().map(i => i.json);
const sums = $('Backlink Summary').all().map(i => i.json);
const gapRes = $input.first().json || {};

const rows = targets.map((t, i) => {
  const task = sums[i]?.tasks?.[0] || {};
  const r = task.result?.[0] || null;
  if (!r) return { domain: t.domain, is_you: t.is_you, available: false, error: task.status_message || sums[i]?.error?.message || 'no data' };
  const rd = r.referring_domains ?? null;
  return {
    domain: t.domain, is_you: t.is_you, available: true,
    domain_rank: r.rank ?? null,
    backlinks: r.backlinks ?? null,
    referring_domains: rd,
    dofollow_pct: rd ? Math.round((1 - (r.referring_domains_nofollow || 0) / rd) * 100) : null,
    spam_score: r.backlinks_spam_score ?? null,
    broken_backlinks: r.broken_backlinks ?? null
  };
});

const available = rows.some(r => r.available);
const you = rows.find(r => r.is_you) || {};
const comps = rows.filter(r => !r.is_you && r.available);
const median = (arr) => { const a = arr.filter(v => v != null).sort((x, y) => x - y); if (!a.length) return null; const m = Math.floor(a.length / 2); return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2; };
const medians = {
  referring_domains: median(comps.map(c => c.referring_domains)),
  backlinks: median(comps.map(c => c.backlinks)),
  domain_rank: median(comps.map(c => c.domain_rank))
};

const gapItems = gapRes.tasks?.[0]?.result?.[0]?.items || [];
const gap = gapItems.map(it => {
  const vals = Object.values(it.domain_intersection || {});
  const first = vals[0] || {};
  return { referring_domain: first.domain || it.domain || it.referring_domain || null, rank: first.rank ?? null, links_to_competitors: vals.length };
}).filter(g => g.referring_domain).slice(0, 25);

const findings = [];
const works = [];
const F = (severity, title, evidence, why, fix) => findings.push({
  category: 'Authority', severity, title, evidence, why, fix,
  sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site'
});

if (!available) {
  F('Info', 'Backlink data not available', 'Backlinks API returned: ' + (rows[0] && rows[0].error || 'no data'),
    'Backlink numbers need the DataForSEO Backlinks API to be active.', 'Activate the Backlinks API to include link authority in the next report.');
} else if (you.available) {
  if (medians.referring_domains && (you.referring_domains || 0) < medians.referring_domains * 0.1) {
    F('High', 'Far fewer referring domains than competitors',
      you.referring_domains + ' referring domains vs competitor median ' + Math.round(medians.referring_domains),
      'Links from other websites are one of the strongest ranking signals; competitors are far ahead.',
      'Earn links from partner directories, industry associations, suppliers, press and guest content.');
  } else if (medians.referring_domains && you.referring_domains >= medians.referring_domains) {
    works.push('Referring domains on par with competitors (' + you.referring_domains + ' vs median ' + Math.round(medians.referring_domains) + ')');
  }
  if (you.dofollow_pct != null && you.dofollow_pct < 50 && you.referring_domains > 5) {
    F('Low', 'Most links are nofollow', you.dofollow_pct + '% of referring domains give followed links',
      'Nofollow links pass little ranking value.', 'Prioritise editorial links, directories and partners that give followed links.');
  }
  if (you.spam_score != null && you.spam_score > 30) {
    F('Medium', 'High backlink spam score', 'Spam score ' + you.spam_score,
      'A high share of low-quality links can hold rankings back.', 'Review the worst linking domains and disavow clearly manipulative ones.');
  }
  if (you.broken_backlinks > 10) {
    F('Low', 'Backlinks pointing to broken pages', you.broken_backlinks + ' backlinks lead to pages that no longer exist',
      'Link value is lost when links point to 404 pages.', 'Redirect the old URLs to the most relevant live pages.');
  }
}
if (gap.length) {
  F('Medium', 'Link opportunities: sites that link to competitors but not to you',
    gap.length + ' domains. Top: ' + gap.slice(0, 5).map(g => g.referring_domain).join(', '),
    'Sites that already link to your competitors are the most likely to link to you.',
    'Reach out to these sites with a listing request, partnership or useful resource.');
}

return [{
  json: {
    ...base,
    authority: { available, rows, medians, gap },
    extra_findings: [...(base.extra_findings || []), ...findings],
    extra_works: [...(base.extra_works || []), ...works]
  }
}];

const base = $('Analyze Backlinks').first().json;
const targets = $('PS Targets').all().map(i => i.json);
const res = $input.all().map(i => i.json);

const rows = targets.map((t, i) => {
  const r = res[i] || {};
  const lr = r.lighthouseResult || {};
  const a = lr.audits || {};
  const sc = lr.categories?.performance?.score;
  const f = r.loadingExperience?.metrics || {};
  const opps = Object.values(a)
    .filter(x => x && x.details && x.details.type === 'opportunity' && (x.details.overallSavingsMs || 0) > 100)
    .sort((x, y) => y.details.overallSavingsMs - x.details.overallSavingsMs)
    .slice(0, 6)
    .map(x => ({ title: x.title, savings_ms: Math.round(x.details.overallSavingsMs), display: x.displayValue || '' }));
  return {
    domain: t.domain, is_you: t.is_you,
    available: sc != null,
    score: sc != null ? Math.round(sc * 100) : null,
    lab: {
      lcp: a['largest-contentful-paint']?.numericValue ?? null,
      cls: a['cumulative-layout-shift']?.numericValue ?? null,
      tbt: a['total-blocking-time']?.numericValue ?? null,
      ttfb: a['server-response-time']?.numericValue ?? null,
      tti: a['interactive']?.numericValue ?? null
    },
    field: {
      lcp: f.LARGEST_CONTENTFUL_PAINT_MS?.percentile ?? null,
      cls: f.CUMULATIVE_LAYOUT_SHIFT_SCORE?.percentile != null ? f.CUMULATIVE_LAYOUT_SHIFT_SCORE.percentile / 100 : null,
      inp: f.INTERACTION_TO_NEXT_PAINT?.percentile ?? null,
      overall: r.loadingExperience?.overall_category || null
    },
    opportunities: opps
  };
});

const you = rows.find(r => r.is_you) || {};
const comps = rows.filter(r => !r.is_you && r.available);
const median = (arr) => { const a = arr.filter(v => v != null).sort((x, y) => x - y); if (!a.length) return null; const m = Math.floor(a.length / 2); return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2; };
const medians = { score: median(comps.map(c => c.score)) };

const findings = [];
const works = [];
const F = (severity, title, evidence, why, fix) => findings.push({
  category: 'Performance', severity, title, evidence, why, fix,
  sample_urls: ['https://' + base.domain + '/'], affected_count: null, affected_pct: 100, scope: 'site'
});

if (you.available) {
  const lcp = you.field.lcp ?? you.lab.lcp;
  const lcpSrc = you.field.lcp != null ? 'real users' : 'lab test';
  if (lcp > 4000) F('High', 'Largest Contentful Paint is Poor (over 4s)', Math.round(lcp) + 'ms (' + lcpSrc + ', mobile)', 'Google rates LCP over 4 seconds as Poor; it hurts rankings and conversions.', 'Speed up server response, preload the main image and reduce render-blocking resources.');
  else if (lcp > 2500) F('Medium', 'Largest Contentful Paint needs improvement (2.5-4s)', Math.round(lcp) + 'ms (' + lcpSrc + ', mobile)', 'Google rates LCP above 2.5 seconds as Needs Improvement.', 'Speed up server response and optimise the main image.');
  else if (lcp) works.push('Good Largest Contentful Paint (' + Math.round(lcp) + 'ms, ' + lcpSrc + ')');

  const cls = you.field.cls ?? you.lab.cls;
  if (cls > 0.25) F('High', 'Layout shift is Poor (CLS over 0.25)', 'CLS ' + Number(cls).toFixed(2), 'Content jumping while loading frustrates users and fails Core Web Vitals.', 'Reserve space for images, banners and embeds.');
  else if (cls > 0.1) F('Medium', 'Layout shift needs improvement (CLS 0.1-0.25)', 'CLS ' + Number(cls).toFixed(2), 'Visible layout shifts hurt user experience.', 'Set width/height on images and reserve space for dynamic content.');
  else if (cls != null) works.push('Stable layout (CLS ' + Number(cls).toFixed(2) + ')');

  if (you.field.inp > 500) F('High', 'Slow response to clicks and taps (INP over 500ms)', 'INP ' + you.field.inp + 'ms (real users)', 'Pages that react slowly feel broken.', 'Reduce and split heavy JavaScript.');
  else if (you.field.inp > 200) F('Medium', 'Response to clicks needs improvement (INP 200-500ms)', 'INP ' + you.field.inp + 'ms (real users)', 'Slow interactions hurt experience.', 'Reduce long JavaScript tasks.');

  if (you.score < 50) F('High', 'Low mobile performance score', 'PageSpeed ' + you.score + '/100 (mobile)', 'A low score signals heavy, slow pages on phones.', 'Fix the top opportunities listed below.');
  else if (you.score < 75) F('Medium', 'Mobile performance score needs improvement', 'PageSpeed ' + you.score + '/100 (mobile)', 'There is clear room to make mobile pages faster.', 'Fix the top opportunities listed below.');
  else if (you.score >= 90) works.push('Excellent mobile PageSpeed score (' + you.score + '/100)');

  if (you.lab.ttfb > 600) F('Medium', 'Slow server response in Lighthouse test', Math.round(you.lab.ttfb) + 'ms server response', 'The first byte arrives slowly, delaying everything else.', 'Enable HTML caching at the CDN and host close to your audience.');
  if (you.lab.tbt > 600) F('Medium', 'Heavy JavaScript blocks the page', 'Total Blocking Time ' + Math.round(you.lab.tbt) + 'ms', 'Long scripts freeze the page after it appears.', 'Defer third-party tags and split large scripts.');
  if (you.opportunities.length) F('Low', 'Top speed-up opportunities', you.opportunities.map(o => o.title + ' (~' + o.savings_ms + 'ms)').join('; '), 'Google lists these as the biggest savings available.', 'Work through these in order of estimated savings.');

  if (medians.score != null && you.score != null && you.score < medians.score - 15) {
    F('High', 'Mobile speed is well behind competitors', 'PageSpeed ' + you.score + ' vs competitor median ' + medians.score, 'Faster competitor pages give them a user-experience and ranking edge.', 'Prioritise caching, image optimisation and JavaScript reduction.');
  }
} else {
  findings.push({ category: 'Performance', severity: 'Info', title: 'PageSpeed test did not return results', evidence: 'Google PageSpeed API gave no data for the homepage', why: 'Core Web Vitals could not be measured in this run.', fix: 'Check the API key and try again.', sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site' });
}

return [{
  json: {
    ...base,
    pagespeed: { rows, medians },
    extra_findings: [...(base.extra_findings || []), ...findings],
    extra_works: [...(base.extra_works || []), ...works]
  }
}];

const comps = $('Pick Competitors').all().map(i => i.json).filter(c => !c.is_you);
if (!comps.length) return [{ json: { domain: '', url: 'https://example.com/', skip: true } }];
return comps.map(c => ({ json: { domain: c.domain, url: 'https://' + c.domain + '/', skip: false } }));

const base = $('Analyze PageSpeed').first().json;
const strip = (s) => String(s || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

const picked = $('Pick Key Pages').all().map(i => i.json);
const fetched = $('Fetch Page HTML').all().map(i => i.json);

const parts = [];
picked.forEach((p, i) => {
  if (!p || !p.url) return;
  const f = fetched[i] || {};
  const text = strip(f.html || f.body || f.data || '');
  if (text.length < 200) return;
  parts.push('=== ' + String(p.kind || 'page').toUpperCase() + ': ' + p.url + ' ===\n' + text.slice(0, 2500));
});
const ours = parts.join('\n\n').slice(0, 22000);
const content_skip = ours.length < 800;

const homes = $('Competitor Homes').all().map(i => i.json);
const reads = $input.all().map(i => i.json);
const comp = homes.map((h, i) => h.skip ? '' : '=== COMPETITOR: ' + h.domain + ' ===\n' +
  String((reads[i] || {}).page_text || '')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/\s+/g, ' ').slice(0, 3000)).filter(t => t.length > 300).join('\n\n');

return [{
  json: {
    ...base,
    content_skip,
    content_pages_read: parts.length,
    content_prompt_our: content_skip ? 'NO_CONTENT' : ours,
    content_prompt_comp: comp || 'NO_COMPETITOR_CONTENT'
  }
}];

parameters.text:
=You are a senior SEO and E-E-A-T auditor. Review the website below for content quality and trust, and compare it with competitors.

Website: {{ $json.domain }}
Target country: {{ $json.country }}

OUR KEY PAGES (raw text):
{{ $json.content_prompt_our }}

COMPETITOR HOMEPAGES (raw text):
{{ $json.content_prompt_comp }}

If OUR KEY PAGES is exactly NO_CONTENT, return only: {"skipped": true}

Otherwise return ONLY a valid JSON object (no markdown, no backticks):
{
  "business_context": "1-2 sentences: what the business does, who it serves and where",
  "eeat_signals": {
    "named_authors": "yes | no | partial",
    "case_studies": "yes | no | partial",
    "testimonials_reviews": "yes | no | partial",
    "credentials_certifications": "yes | no | partial",
    "pricing_transparency": "yes | no | partial",
    "team_or_leadership_info": "yes | no | partial",
    "clear_contact_details": "yes | no | partial"
  },
  "findings": [
    { "severity": "Critical | High | Medium | Low", "title": "", "evidence": "exact quote or specific observation from the text", "why": "", "fix": "", "url": "page URL where seen" }
  ],
  "strengths": ["specific things the site does well, based on the text"],
  "competitor_comparison": [
    { "domain": "", "named_authors": "yes | no | unclear", "case_studies": "yes | no | unclear", "testimonials": "yes | no | unclear", "pricing": "yes | no | unclear", "content_depth": "thin | moderate | deep", "standout": "one line on what they do better or worse" }
  ],
  "binding_constraint": "One sentence: the single biggest thing holding this site back, based on content and trust"
}

Rules:
- Report only what the text shows. Every finding must quote or point to specific text. Never invent facts, clients or numbers.
- Do not report something as missing unless you have read the pages where it would normally appear (e.g. contact details on the contact page).
- If COMPETITOR HOMEPAGES is NO_COMPETITOR_CONTENT, return an empty competitor_comparison array.
- Look for: contradicting claims (years of experience vs dates), unproven claims (partner, certified, client base), missing proof (case studies, reviews, named experts), vague service pages, missing pricing or timelines, only high-commitment calls to action, placeholder text, formatting artifacts.
- 4 to 10 findings, most important first.
- Write in {{ $json.language_name || 'English' }}.

parameters.jsCode:
// Accepts an object (from the Structured Output Parser) or a string with/without code fences or surrounding text
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  throw new Error('AI did not return valid JSON. Output was: ' + s.slice(0, 300));
};

const base = $('Build Content Prompt').first().json;
let cr = null;
try { cr = parseAgentJson($input.first().json.output); } catch (e) { cr = null; }

const findings = [];
const works = [];
const skipped = base.content_skip || (cr && cr.skipped);

if (skipped) {
  findings.push({ category: 'Content', severity: 'Info', title: 'Content review skipped: page text could not be read',
    evidence: 'Readable text was collected from ' + (base.content_pages_read || 0) + ' pages',
    why: 'Content and E-E-A-T could not be assessed in this run, so no content findings were reported.',
    fix: 'Re-run the report; if this repeats, the pages may block automated readers.',
    sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site' });
  cr = null;
} else if (cr) {
  for (const f of (cr.findings || [])) {
    let sev = ['Critical', 'High', 'Medium', 'Low'].includes(f.severity) ? f.severity : 'Medium';
    if (sev === 'Critical') sev = 'High';                       // AI review never outranks measured technical issues
    findings.push({
      category: 'Content', severity: sev, title: f.title || 'Content issue',
      evidence: f.evidence || '', why: f.why || '', fix: f.fix || '',
      sample_urls: f.url ? [f.url] : [], affected_count: null, affected_pct: 100, scope: 'site', scoring: false, source: 'ai_review'
    });
  }
  (cr.strengths || []).forEach(s => works.push(s));
} else {
  findings.push({ category: 'Content', severity: 'Info', title: 'Content review could not be completed', evidence: 'AI response was not valid JSON', why: '', fix: 'Re-run the report.', sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site' });
}

const clean = { ...base };
delete clean.content_prompt_our;
delete clean.content_prompt_comp;

return [{
  json: {
    ...clean,
    content_review: cr,
    extra_findings: [...(base.extra_findings || []), ...findings],
    extra_works: [...(base.extra_works || []), ...works]
  }
}];

// Live Google queries for the AI-visibility and brand checks. Each item becomes one SERP request.
const base = $input.first().json;
const brandName = String(((base.content_review || {}).business_context || '').match(/^([A-Z][\w&.-]+(?:\s[A-Z][\w&.-]+){0,2})/) || [])[1] || base.domain.split('.')[0];

const sk = base.site_keywords || {};
const pool = [
  ...(sk.keyword_gap || []),
  ...Object.values(sk.opportunities_by_intent || {}).flat(),
  ...Object.values(sk.your_top_by_intent || {}).flat()
].filter(k => ['commercial', 'transactional'].includes(k.intent))
 .sort((a, b) => (b.volume || 0) - (a.volume || 0));

// Category query: what a buyer types to find this type of business in the target country
let category = '';
const seeds = (sk.seeds || []).filter(Boolean);
if (pool[0]) category = pool[0].keyword;
else if (seeds[0]) category = seeds[0];
if (category && !/\b(company|companies|agency|agencies|services?|providers?|firms?|best|top)\b/i.test(category)) category = 'best ' + category + ' company';
if (category && base.country && !category.toLowerCase().includes(String(base.country).toLowerCase())) category = category + ' ' + base.country;

const queries = [
  { query: brandName.toLowerCase(), type: 'brand' },
  { query: 'site:' + base.domain, type: 'index' }
];
if (category) queries.push({ query: category.toLowerCase(), type: 'category' });
if (pool[0] && pool[0].keyword !== category) queries.push({ query: pool[0].keyword, type: 'top keyword' });

const seen = new Set();
return queries.filter(q => q.query && !seen.has(q.query) && seen.add(q.query))
  .map(q => ({ json: { ...q, brand_name: brandName, category_query: category } }));

const base = $('Parse Content Review').first().json;
const qs = $('AI Queries').all().map(i => i.json);
const serps = $('AI SERP').all().map(i => i.json);
const prompts = $('LLM Prompts').all().map(i => i.json);
const answers = $input.all().map(i => i.json);

const ours = base.domain;
const brandTok = String((qs[0] || {}).brand_name || ours.split('.')[0]).toLowerCase();
const compDomains = ((base.competitor_benchmark || {}).rows || []).filter(r => !r.is_you).map(r => r.domain);
const norm = (d) => String(d || '').toLowerCase().replace(/^www\./, '');
const matches = (d, target) => { d = norm(d); return d === target || d.endsWith('.' + target); };
const hostOf = (u) => norm(String(u || '').replace(/^https?:\/\//, '').split(/[\/?#]/)[0]);

// ---------- Google results ----------
let indexEstimate = null;
const rows = qs.map((q, i) => {
  const res = serps[i]?.tasks?.[0]?.result?.[0] || {};
  const items = res.items || [];
  if (q.type === 'index') { indexEstimate = res.se_results_count ?? null; }
  const aio = items.find(x => x.type === 'ai_overview');
  const refs = [];
  if (aio) {
    (aio.references || []).forEach(r => refs.push(r.domain || r.url));
    (aio.items || []).forEach(it => (it.references || []).forEach(r => refs.push(r.domain || r.url)));
  }
  const cited = [...new Set(refs.filter(Boolean).map(r => hostOf(String(r).includes('://') ? r : 'https://' + r)))];
  const organic = items.filter(x => x.type === 'organic');
  const pos = (target) => { const o = organic.find(x => matches(x.domain, target)); return o ? o.rank_group : null; };
  const compPos = {};
  compDomains.forEach(c => compPos[c] = pos(c));
  return {
    query: q.query, type: q.type,
    ai_overview: !!aio,
    cited_domains: cited.slice(0, 10),
    you_cited: cited.some(c => matches(c, ours)),
    competitors_cited: compDomains.filter(c => cited.some(x => matches(x, c))),
    your_position: pos(ours),
    competitor_positions: compPos,
    serp_features: [...new Set(items.map(x => x.type))].filter(t => t !== 'organic')
  };
}).filter(r => r.type !== 'index');

// ---------- LLM answers (DataForSEO LLM Responses) ----------
const llm = prompts.map((p, i) => {
  const j = answers[i] || {};
  const task = j.tasks?.[0] || {};
  const result = task.result?.[0] || null;
  const items = (result && result.items) || [];
  const texts = [];
  const urls = [];
  items.forEach(it => (it.sections || []).forEach(s => {
    if (s.text) texts.push(s.text);
    (s.annotations || []).forEach(a => { if (a.url) urls.push(a.url); });
  }));
  const text = texts.join('\n');
  const domainsInText = [...new Set([...(text.match(/\b([a-z0-9-]+\.)+[a-z]{2,}\b/gi) || []).map(norm), ...urls.map(hostOf)])]
    .filter(d => d && !/^(openai|perplexity|google|bing|wikipedia|linkedin|facebook|youtube|reddit|x|twitter|instagram)\.(com|org|ai)$/.test(d));
  const mentionsYou = domainsInText.some(d => matches(d, ours)) || new RegExp('\\b' + brandTok.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(text);
  const notFound = /could not find|couldn't find|no information|not familiar|unable to find|don't have (any )?information/i.test(text);
  return {
    platform: p.platform, kind: p.kind, prompt: p.prompt,
    ok: !!result && !j.error && !(task.status_code >= 40000),
    error: j.error ? (j.error.message || String(j.error)).slice(0, 120) : (task.status_code >= 40000 ? task.status_message : ''),
    answer: text.slice(0, 1200),
    cited_sources: [...new Set(urls.map(hostOf))].slice(0, 10),
    domains_mentioned: domainsInText.slice(0, 12),
    mentions_you: mentionsYou,
    not_found: notFound && !mentionsYou,
    competitors_mentioned: compDomains.filter(c => domainsInText.some(d => matches(d, c))),
    cost_usd: task.cost ?? null
  };
});

const findings = [];
const works = [];
const F = (severity, title, evidence, why, fix) => findings.push({
  category: 'AI Search Readiness', severity, title, evidence, why, fix,
  sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site'
});

const who = llm.find(x => x.kind === 'who');
if (who && who.ok) {
  if (who.not_found || !who.mentions_you) F('High', 'ChatGPT cannot describe the company', 'Asked "what is ' + brandTok + ' (' + ours + ')" with web search on: ' + (who.answer.slice(0, 220) || 'no answer'),
    'If AI assistants cannot identify you from your own site and third-party mentions, they will not recommend or cite you.',
    'Publish a clear About page and Organization schema, and build consistent third-party profiles (directories, LinkedIn, review sites, Wikidata) using one exact brand name.');
  else works.push('ChatGPT (with web search) correctly identifies the company');
}
const recs = llm.filter(x => x.kind === 'recommend' && x.ok);
recs.forEach(r => {
  const platform = r.platform === 'chat_gpt' ? 'ChatGPT' : 'Perplexity';
  if (!r.mentions_you && r.domains_mentioned.length) {
    F('High', platform + ' recommends other providers, not you',
      'For "' + r.prompt.slice(0, 120) + '…" ' + platform + ' listed: ' + r.domains_mentioned.slice(0, 6).join(', ') + (r.competitors_mentioned.length ? ' (including competitors ' + r.competitors_mentioned.join(', ') + ')' : ''),
      'Buyers increasingly ask AI assistants for shortlists; not being named means not being considered.',
      'Get listed where AI answers draw their sources: the directories and review sites cited (' + (r.cited_sources.slice(0, 4).join(', ') || 'see report') + '), plus comparison and "best X" pages that name you.');
  } else if (r.mentions_you) works.push(platform + ' includes you when recommending providers in your category');
});
const failed = llm.filter(x => !x.ok);
if (failed.length === llm.length && llm.length) {
  findings.push({ category: 'AI Search Readiness', severity: 'Info', title: 'AI assistant checks did not return results', evidence: failed.map(f => f.platform + ': ' + (f.error || 'no data')).join('; '), why: 'The LLM Responses API (DataForSEO AI Optimization) needs to be enabled on the account.', fix: 'Enable the AI Optimization API in DataForSEO and re-run.', sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site', scoring: false });
}

rows.forEach(r => {
  if (r.ai_overview && !r.you_cited && r.competitors_cited.length) {
    F('High', 'Competitors are cited in Google AI Overviews, you are not',
      '"' + r.query + '": AI Overview cites ' + r.competitors_cited.join(', '),
      'AI Overviews sit above normal results and take clicks.',
      'Publish clear, well-sourced answer blocks on this topic and strengthen entity signals.');
  } else if (r.ai_overview && !r.you_cited && r.type !== 'brand') {
    F('Medium', 'Google shows an AI Overview for "' + r.query + '" and does not cite you',
      'Cited: ' + (r.cited_domains.slice(0, 6).join(', ') || 'sources not listed'),
      'The query already has an AI answer; pages that are not cited lose visibility.',
      'Add a concise 40-70 word answer block, question-style headings and cite primary sources on the relevant page.');
  } else if (r.you_cited) works.push('Cited in Google AI Overview for "' + r.query + '"');
});

const brandRow = rows.find(r => r.type === 'brand');
if (brandRow) {
  if (brandRow.your_position == null || brandRow.your_position > 3) {
    F('High', 'Site does not rank at the top for its own brand name',
      'Search "' + brandRow.query + '": your position ' + (brandRow.your_position || 'not in top 20'),
      'If people cannot find you by name, every other channel (ads, referrals, AI) leaks visitors.',
      'Use one consistent brand name everywhere, add Organization schema with alternateName, and build branded mentions.');
  } else works.push('Ranks #' + brandRow.your_position + ' for its brand name');
}

// Index coverage estimate (site: operator vs crawl)
const crawled = base.pages_crawled || null;
if (indexEstimate != null && crawled) {
  if (indexEstimate < crawled * 0.5) {
    findings.push({ category: 'Crawlability & Indexing', severity: 'High', title: 'Far fewer pages indexed than crawled', evidence: 'Google site: estimate ' + indexEstimate + ' vs ' + crawled + ' crawlable pages', why: 'Pages that are not indexed cannot rank. This is an estimate; confirm in Search Console.', fix: 'Check Search Console → Pages for "Crawled – currently not indexed" and "Discovered – currently not indexed", improve internal links and content depth on those URLs.', sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site' });
  } else if (indexEstimate > crawled * 3) {
    findings.push({ category: 'Crawlability & Indexing', severity: 'Medium', title: 'Many more URLs indexed than the crawl found (index bloat)', evidence: 'Google site: estimate ' + indexEstimate + ' vs ' + crawled + ' crawlable pages', why: 'Old, parameter or tag URLs that stay indexed dilute crawl budget and quality signals.', fix: 'Review indexed URLs in Search Console; noindex or remove thin/duplicate URLs and fix the sitemap.', sample_urls: [], affected_count: null, affected_pct: 100, scope: 'site' });
  } else works.push('Google indexes roughly as many pages as the crawl found (' + indexEstimate + ' estimated)');
}

return [{
  json: {
    ...base,
    ai_visibility: {
      brand_name: brandTok,
      queries: rows,
      llm_answers: llm,
      index_estimate: indexEstimate,
      note: 'AI assistant checks are live answers from ChatGPT (web search on) and Perplexity via the DataForSEO LLM Responses API; each run may differ slightly. Google AI Overview data comes from a live search.'
    },
    extra_findings: [...(base.extra_findings || []), ...findings],
    extra_works: [...(base.extra_works || []), ...works]
  }
}];

const d = $input.first().json;
const a = d.site_audit || {};
const cb = a.competitor_benchmark || d.competitor_benchmark || { rows: [] };
const sk = d.site_keywords || null;
const au = d.authority || null;
const ps = d.pagespeed || null;
const cr = d.content_review || null;
const av = d.ai_visibility || null;

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = (n) => (n == null || n === '' || isNaN(n)) ? 'N/A' : Number(n).toLocaleString('en-GB');
const ms = (n) => n == null ? 'N/A' : (n >= 1000 ? (n / 1000).toFixed(2) + 's' : Math.round(n) + 'ms');
const today = new Date().toISOString().slice(0, 10);
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

const SEV = ['Critical', 'High', 'Medium', 'Low', 'Info'];
const SEV_COLOR = { Critical: '#B91C1C', High: '#EA580C', Medium: '#CA8A04', Low: '#2563EB', Info: '#64748B' };
const scoreColor = (s) => s >= 90 ? '#15803D' : s >= 75 ? '#65A30D' : s >= 60 ? '#CA8A04' : '#B91C1C';
const bar = (s) => `<table class="bar"><tr><td style="width:${s}%;background:${scoreColor(s)}">&nbsp;</td><td style="width:${100 - s}%;background:#E2E8F0">&nbsp;</td></tr></table>`;
const yn = (v) => { const t = String(v || '').toLowerCase(); const c = t === 'yes' ? '#15803D' : t === 'no' ? '#B91C1C' : '#CA8A04'; return `<b style="color:${c}">${esc(v || 'unclear')}</b>`; };
const youTag = (r) => r.is_you ? '<b>' + esc(r.domain) + ' (you)</b>' : esc(r.domain);
const diffLabel = (v) => v == null ? 'N/A' : v + (v < 30 ? ' (easy)' : v < 50 ? ' (medium)' : v < 70 ? ' (hard)' : ' (very hard)');

const findings = a.findings || [];
const counts = a.issue_counts || {};
const byCat = (cat) => findings.filter(f => f.category === cat);

function card(f) {
  const scope = f.scope === 'site' ? 'Whole website' : `${f.affected_count} of ${a.pages_crawled} pages (${f.affected_pct}%)`;
  const urls = f.sample_urls || [];
  return `<div class="finding" style="border-left-color:${SEV_COLOR[f.severity]}">
    <div class="ftitle"><span class="badge" style="background:${SEV_COLOR[f.severity]}">${f.severity}</span> ${esc(f.title)}</div>
    <div class="fmeta">${esc(scope)}</div>
    ${f.evidence ? '<p><b>Evidence:</b> ' + esc(f.evidence) + '</p>' : ''}
    ${f.why ? '<p><b>Why it matters:</b> ' + esc(f.why) + '</p>' : ''}
    ${f.fix ? '<p><b>How to fix:</b> ' + esc(f.fix) + '</p>' : ''}
    ${urls.length ? '<p class="small"><b>Affected pages:</b><br>' + urls.map(esc).join('<br>') + (f.affected_count > urls.length ? '<br>…and ' + (f.affected_count - urls.length) + ' more' : '') + '</p>' : ''}
  </div>`;
}
const findingsBlock = (list) => list.length
  ? SEV.map(s => list.filter(f => f.severity === s).map(card).join('')).join('')
  : '<p class="okline">No issues found in this area.</p>';

// ---------- Merged benchmark ----------
const doms = (cb.rows || []).map(r => r.domain);
const get = (arr, dom) => (arr || []).find(x => x.domain === dom) || {};
const bench = doms.map(dom => {
  const c = get(cb.rows, dom);
  const k = get(sk && sk.domains, dom);
  const b = get(au && au.rows, dom);
  const p = get(ps && ps.rows, dom);
  return { domain: dom, is_you: c.is_you, keywords: k.total ?? c.organic_keywords, top10: k.top10 ?? c.top10, traffic: c.est_monthly_traffic, value: c.traffic_value_usd, age: c.domain_age_years, rd: b.referring_domains, dr: b.domain_rank, speed: p.score, lcp: p.field ? (p.field.lcp ?? (p.lab || {}).lcp) : null };
});
const you = bench.find(b => b.is_you) || {};

const catScores = a.category_scores || {};
const lowest = Object.entries(catScores).sort((x, y) => x[1] - y[1])[0] || ['', 0];
const binding = (cr && cr.binding_constraint) ? cr.binding_constraint : ('The weakest area is ' + lowest[0] + ' (' + lowest[1] + '/100).');

let html = '';

// ---------- Cover ----------
html += `<div class="cover">
  <div class="brand">Full SEO Report</div>
  <h1 class="title">${esc(a.domain)}</h1>
  <p class="sub">${esc(d.country || '')} &nbsp;•&nbsp; ${esc(a.pages_crawled)} pages crawled &nbsp;•&nbsp; ${esc(a.crawl_date || today)}</p>
  <table class="scorebox"><tr>
    <td class="big" style="color:${scoreColor(a.health_score)}">${esc(a.health_score)}<span>/100</span></td>
    <td><div class="grade">${esc(a.grade)}</div><div class="lbl">SEO Health Score</div></td>
  </tr></table>
  <p class="by">Prepared by ${esc(d.brand || 'Dev SEO')}</p>
</div>`;

// ---------- Contents ----------
const TOC = ['Executive Summary', 'Scorecard', 'Competitor Benchmark', 'Keywords by Search Intent', 'Authority & Backlinks', 'Content Quality & E-E-A-T', 'Performance & Core Web Vitals', 'AI Search Visibility', 'Structured Data (Schema)', 'Crawlability & Indexing', 'On-Page SEO', 'Images, Security & Technical', 'What Works Well', 'Action Plan', 'Leading Indicators', 'Methodology & Data Sources'];
html += '<h2>Contents</h2><ol class="toc">' + TOC.map(t => '<li>' + t + '</li>').join('') + '</ol>';

// ---------- 1. Executive summary ----------
const top = findings.filter(f => f.severity === 'Critical' || f.severity === 'High').slice(0, 7);
html += `<h2 class="pb">1. Executive Summary</h2>
${cr && cr.business_context ? '<p><b>About the site:</b> ' + esc(cr.business_context) + '</p>' : ''}
<div class="callout"><b>The main thing holding this site back:</b> ${esc(binding)}</div>
<table class="ct"><tr>${SEV.map(s => `<th style="background:${SEV_COLOR[s]}">${s}</th>`).join('')}</tr>
<tr>${SEV.map(s => `<td style="text-align:center;font-size:14pt"><b>${counts[s] || 0}</b></td>`).join('')}</tr></table>
${a.score_cap_reason ? `<div class="note"><b>Score limit applied:</b> ${esc(a.score_cap_reason)}. Calculated score before the limit: ${esc(a.raw_score)}/100.</div>` : ''}
<h3>Key Numbers: You vs Competitors</h3>
<table class="ct"><tr><th>Metric</th><th>You</th><th>Competitor median</th></tr>
<tr><td>Keywords ranking (top 30)</td><td>${num(you.keywords)}</td><td>${num(cb.medians && cb.medians.organic_keywords)}</td></tr>
<tr><td>Keywords in top 10</td><td>${num(you.top10)}</td><td>${num(cb.medians && cb.medians.top10)}</td></tr>
<tr><td>Estimated monthly organic visits</td><td>${num(you.traffic)}</td><td>${num(cb.medians && cb.medians.est_monthly_traffic)}</td></tr>
<tr><td>Referring domains</td><td>${num(you.rd)}</td><td>${num(au && au.medians && au.medians.referring_domains)}</td></tr>
<tr><td>Mobile PageSpeed</td><td>${num(you.speed)}</td><td>${num(ps && ps.medians && ps.medians.score)}</td></tr>
<tr><td>Domain age (years)</td><td>${num(you.age)}</td><td>${num(cb.medians && cb.medians.domain_age_years)}</td></tr></table>
${top.length ? '<h3>Fix These First</h3><ol>' + top.map(f => `<li><b>${esc(f.title)}</b>${f.evidence ? ' <span class="small">(' + esc(f.evidence) + ')</span>' : ''}<br>${esc(f.fix)}</li>`).join('') + '</ol>' : ''}`;

// ---------- 2. Scorecard ----------
html += `<h2>2. Scorecard</h2><table class="ct"><tr><th>Category</th><th style="width:60px">Score</th><th style="width:60px">Weight</th><th style="width:45%"></th></tr>` +
  Object.entries(catScores).map(([cat, s]) => `<tr><td>${esc(cat)}</td><td><b style="color:${scoreColor(s)}">${s}</b></td><td>${esc((a.weights || {})[cat])}%</td><td>${bar(s)}</td></tr>`).join('') + `</table>`;

// ---------- 3. Competitor benchmark ----------
html += `<h2 class="pb">3. Competitor Benchmark</h2>
<p class="small">Competitors: ${esc(cb.source || '')}. Country: ${esc(d.country || '')}.</p>
<table class="ct"><tr><th>Domain</th><th>Keywords</th><th>Top 10</th><th>Est. visits/mo</th><th>Traffic value $</th><th>Ref. domains</th><th>Domain rank</th><th>PageSpeed</th><th>Age (yrs)</th></tr>` +
  bench.map(b => `<tr${b.is_you ? ' class="you"' : ''}><td>${youTag(b)}</td><td>${num(b.keywords)}</td><td>${num(b.top10)}</td><td>${num(b.traffic)}</td><td>${num(b.value)}</td><td>${num(b.rd)}</td><td>${num(b.dr)}</td><td>${num(b.speed)}</td><td>${num(b.age)}</td></tr>`).join('') + `</table>`;

// ---------- 4. Keywords ----------
const INT = ['informational', 'navigational', 'commercial', 'transactional'];
const INT_DESC = {
  informational: 'People researching or learning (how, what, guide)',
  navigational: 'People looking for a specific brand or website',
  commercial: 'People comparing providers before deciding (best, services, company, vs)',
  transactional: 'People ready to act (price, cost, hire, buy, quote)'
};
const compCell = (list) => (list || []).length ? list.map(c => esc(c.domain) + ' #' + c.position).join('<br>') : '—';

html += `<h2 class="pb">4. Keywords by Search Intent</h2>`;
if (sk) {
  if ((sk.seeds || []).length) html += `<p class="small">Keyword research based on your services: ${esc(sk.seeds.join(', '))}</p>`;

  html += `<h3>Current Rankings per Intent (top 30): You vs Competitors</h3><table class="ct"><tr><th>Intent</th>` +
    sk.domains.map(x => `<th>${esc(x.domain)}${x.is_you ? ' (you)' : ''}</th>`).join('') + `</tr>` +
    INT.map(i => `<tr><td>${cap(i)}</td>` + sk.domains.map(x => `<td>${num(x.by_intent[i])}</td>`).join('') + `</tr>`).join('') + `</table>`;

  const hasOwn = INT.some(i => ((sk.your_top_by_intent || {})[i] || []).length);
  if (hasOwn) {
    INT.forEach(i => {
      const list = (sk.your_top_by_intent || {})[i] || [];
      if (!list.length) return;
      html += `<h3>Your Current ${cap(i)} Rankings</h3><table class="ct"><tr><th>Keyword</th><th>Position</th><th>Searches/mo</th><th>Difficulty</th></tr>` +
        list.map(k => `<tr><td>${esc(k.keyword)}</td><td>#${num(k.position)}</td><td>${num(k.volume)}</td><td>${diffLabel(k.difficulty)}</td></tr>`).join('') + `</table>`;
    });
  } else {
    html += `<div class="note">Your site does not rank in the top 30 for any keyword in ${esc(d.country || 'this market')} yet. The opportunities below show which searches to target, grouped by search intent.</div>`;
  }

  html += `<h2>4a. Keyword Opportunities by Search Intent</h2>`;
  INT.forEach(i => {
    const list = (sk.opportunities_by_intent || {})[i] || [];
    html += `<h3>${cap(i)} Keywords</h3><p class="small">${INT_DESC[i]}</p>` + (list.length
      ? `<table class="ct"><tr><th>Keyword</th><th>Searches/mo</th><th>Difficulty</th><th>CPC $</th><th>Your position</th><th>Competitors in top 10</th></tr>` +
        list.map(k => `<tr><td>${esc(k.keyword)}</td><td>${num(k.volume)}</td><td>${diffLabel(k.difficulty)}</td><td>${k.cpc == null ? 'N/A' : k.cpc}</td><td>${k.your_position ? '#' + k.your_position : '—'}</td><td class="small">${compCell(k.competitors)}</td></tr>`).join('') + `</table>`
      : '<p>No keywords with measurable search volume found for this intent.</p>');
  });

  if ((sk.easy_wins || []).length) {
    html += `<h3>Easy Wins (difficulty under 30)</h3><table class="ct"><tr><th>Keyword</th><th>Intent</th><th>Searches/mo</th><th>Difficulty</th><th>Competitors in top 10</th></tr>` +
      sk.easy_wins.map(k => `<tr><td>${esc(k.keyword)}</td><td>${cap(k.intent)}</td><td>${num(k.volume)}</td><td>${num(k.difficulty)}</td><td class="small">${compCell(k.competitors)}</td></tr>`).join('') + `</table>`;
  }

  html += `<h3>Keyword Gap: Competitors Rank, You Don't</h3>` + ((sk.keyword_gap || []).length
    ? `<table class="ct"><tr><th>Keyword</th><th>Searches/mo</th><th>Difficulty</th><th>Intent</th><th>Competitors ranking</th></tr>` + sk.keyword_gap.slice(0, 20).map(g => `<tr><td>${esc(g.keyword)}</td><td>${num(g.volume)}</td><td>${diffLabel(g.difficulty)}</td><td>${cap(g.intent)}</td><td class="small">${compCell(g.competitors)}</td></tr>`).join('') + `</table>`
    : '<p>No keyword gap found.</p>');

  if ((sk.striking_distance || []).length) {
    html += `<h3>Quick Wins: Keywords on Page 2</h3><table class="ct"><tr><th>Keyword</th><th>Position</th><th>Searches/mo</th><th>Ranking page</th></tr>` +
      sk.striking_distance.map(k => `<tr><td>${esc(k.keyword)}</td><td>#${k.position}</td><td>${num(k.volume)}</td><td class="small">${esc(k.url)}</td></tr>`).join('') + `</table>`;
  }
} else html += '<p>Keyword data was not collected in this run.</p>';

// ---------- 5. Authority & backlinks ----------
html += `<h2 class="pb">5. Authority & Backlinks</h2>`;
if (au && au.available) {
  html += `<table class="ct"><tr><th>Domain</th><th>Domain rank</th><th>Backlinks</th><th>Referring domains</th><th>Followed %</th><th>Spam score</th></tr>` +
    au.rows.map(r => `<tr${r.is_you ? ' class="you"' : ''}><td>${youTag(r)}</td><td>${num(r.domain_rank)}</td><td>${num(r.backlinks)}</td><td>${num(r.referring_domains)}</td><td>${r.dofollow_pct == null ? 'N/A' : r.dofollow_pct + '%'}</td><td>${num(r.spam_score)}</td></tr>`).join('') + `</table>`;
  if ((au.gap || []).length) html += `<h3>Link Opportunities (link to competitors, not to you)</h3><table class="ct"><tr><th>Website</th><th>Links to # competitors</th></tr>` +
    au.gap.slice(0, 20).map(g => `<tr><td>${esc(g.referring_domain)}</td><td>${num(g.links_to_competitors)}</td></tr>`).join('') + `</table>`;
} else html += '<div class="note">Backlink data was not available for this run (DataForSEO Backlinks API not active).</div>';
html += '<h3>Findings</h3>' + findingsBlock(byCat('Authority'));

// ---------- 6. Content & E-E-A-T ----------
html += `<h2 class="pb">6. Content Quality & E-E-A-T</h2>`;
if (cr) {
  const sig = cr.eeat_signals || {};
  html += `<h3>Trust Signals on Your Site</h3><table class="kv">` + Object.entries(sig).map(([k, v]) => `<tr><td class="k">${esc(k.replace(/_/g, ' '))}</td><td>${yn(v)}</td></tr>`).join('') + `</table>`;
  if ((cr.competitor_comparison || []).length) html += `<h3>Competitors' Trust Signals</h3><table class="ct"><tr><th>Competitor</th><th>Authors</th><th>Case studies</th><th>Testimonials</th><th>Pricing</th><th>Depth</th><th>Note</th></tr>` +
    cr.competitor_comparison.map(c => `<tr><td>${esc(c.domain)}</td><td>${yn(c.named_authors)}</td><td>${yn(c.case_studies)}</td><td>${yn(c.testimonials)}</td><td>${yn(c.pricing)}</td><td>${esc(c.content_depth)}</td><td class="small">${esc(c.standout)}</td></tr>`).join('') + `</table>`;
}
html += '<h3>Findings</h3>' + findingsBlock(byCat('Content'));

// ---------- 7. Performance ----------
html += `<h2 class="pb">7. Performance & Core Web Vitals</h2>`;
if (ps) {
  html += `<table class="ct"><tr><th>Domain</th><th>Mobile score</th><th>LCP</th><th>CLS</th><th>INP (real users)</th><th>TBT</th><th>Server response</th></tr>` +
    ps.rows.map(r => `<tr${r.is_you ? ' class="you"' : ''}><td>${youTag(r)}</td><td>${num(r.score)}</td><td>${ms(r.field.lcp ?? r.lab.lcp)}</td><td>${(r.field.cls ?? r.lab.cls) == null ? 'N/A' : Number(r.field.cls ?? r.lab.cls).toFixed(2)}</td><td>${ms(r.field.inp)}</td><td>${ms(r.lab.tbt)}</td><td>${ms(r.lab.ttfb)}</td></tr>`).join('') + `</table>`;
  const yps = ps.rows.find(r => r.is_you) || {};
  if ((yps.opportunities || []).length) html += '<h3>Biggest Speed Savings (your homepage)</h3><ul>' + yps.opportunities.map(o => `<li>${esc(o.title)} — about ${num(o.savings_ms)}ms</li>`).join('') + '</ul>';
}
html += '<h3>Findings</h3>' + findingsBlock(byCat('Performance'));

// ---------- 8. AI visibility ----------
html += `<h2 class="pb">8. AI Search Visibility</h2>`;
if (av) {
  const llm = av.llm_answers || [];
  const pname = (p) => p === 'chat_gpt' ? 'ChatGPT (web search on)' : p === 'perplexity' ? 'Perplexity' : esc(p);
  if (llm.length) {
    html += `<h3>What AI Assistants Say (live answers)</h3><table class="ct"><tr><th>Assistant</th><th>Question</th><th>Mentions you</th><th>Providers named</th><th>Sources cited</th></tr>` +
      llm.map(x => `<tr><td>${pname(x.platform)}</td><td class="small">${esc(x.prompt)}</td><td>${x.ok ? (x.mentions_you ? '<b style="color:#15803D">Yes</b>' : '<b style="color:#B91C1C">No</b>') : 'No data (' + esc(x.error || 'API unavailable') + ')'}</td><td class="small">${esc((x.domains_mentioned || []).slice(0, 8).join(', ') || '—')}</td><td class="small">${esc((x.cited_sources || []).slice(0, 6).join(', ') || '—')}</td></tr>`).join('') + `</table>`;
    llm.filter(x => x.ok && x.answer).slice(0, 3).forEach(x => { html += `<div class="callout"><b>${pname(x.platform)} — ${esc(x.kind === 'who' ? 'about the company' : 'recommendation')}:</b><br>${esc(x.answer.slice(0, 700))}${x.answer.length > 700 ? '…' : ''}</div>`; });
  }
  if (av.index_estimate != null) html += `<p><b>Google index estimate (site: search):</b> ${num(av.index_estimate)} URLs vs ${num(a.pages_crawled)} pages crawled. Confirm the exact figure in Search Console.</p>`;
  html += `<h3>Google Results & AI Overviews</h3><table class="ct"><tr><th>Search</th><th>AI Overview</th><th>You cited</th><th>Competitors cited</th><th>Your position</th><th>Competitor positions</th></tr>` +
    (av.queries || []).map(q => `<tr><td>${esc(q.query)} <span class="small">(${esc(q.type)})</span></td><td>${q.ai_overview ? 'Yes' : 'No'}</td><td>${q.you_cited ? '<b style="color:#15803D">Yes</b>' : 'No'}</td><td>${esc(q.competitors_cited.join(', ') || '—')}</td><td>${q.your_position ? '#' + q.your_position : 'Not in top 20'}</td><td class="small">${Object.entries(q.competitor_positions || {}).map(([k, v]) => esc(k) + ': ' + (v ? '#' + v : '—')).join('<br>') || '—'}</td></tr>`).join('') + `</table>`;
  html += '<p class="small">' + esc(av.note || '') + '</p>';
}
html += '<h3>Findings</h3>' + findingsBlock(byCat('AI Search Readiness'));

// ---------- 9-12. Other categories ----------
const section = (no, title, cats) => `<h2 class="pb">${no}. ${title}</h2>` + cats.map(c =>
  (cats.length > 1 ? `<h3>${esc(c)} — ${num(catScores[c])}/100</h3>` : `<p><b>Score:</b> ${num(catScores[c])}/100</p>`) + findingsBlock(byCat(c))).join('');
html += section(9, 'Structured Data (Schema)', ['Schema']);
const sp = (a.sampled_pages || []).filter(p => p && p.url);
if (sp.length) html += `<h3>Schema Found on Sampled Pages</h3><table class="ct"><tr><th>Page</th><th>Type</th><th>Schema types</th></tr>` + sp.map(p => `<tr><td class="small">${esc(p.url)}</td><td>${esc(p.kind)}</td><td>${esc((p.schema_types || []).join(', ') || 'none')}</td></tr>`).join('') + `</table>`;
html += section(10, 'Crawlability & Indexing', ['Crawlability & Indexing']);
html += section(11, 'On-Page SEO', ['On-Page']);
html += section(12, 'Images, Security & Technical', ['Images', 'Security', 'Technical']);

// ---------- 13. What works ----------
html += `<h2 class="pb">13. What Works Well</h2><ul class="good">` + (a.what_works || []).map(w => `<li>${esc(w)}</li>`).join('') + `</ul>`;

// ---------- 14. Action plan ----------
const tech = ['Security', 'Crawlability & Indexing', 'Performance', 'Technical', 'Schema'];
const onsite = ['Content', 'On-Page', 'Images', 'Schema'];
const offsite = ['Authority', 'AI Search Readiness'];
const phase = (title, when, list) => list.length ? `<h3>${title} <span class="small">(${when})</span></h3><ul>` + list.map(f => `<li>${esc(f.title)} <span class="small">[${f.severity}]</span></li>`).join('') + '</ul>' : '';
const p1 = findings.filter(f => ['Critical', 'High'].includes(f.severity) && tech.includes(f.category));
const p2 = findings.filter(f => ['Critical', 'High', 'Medium'].includes(f.severity) && onsite.includes(f.category) && !p1.includes(f));
const p3 = findings.filter(f => offsite.includes(f.category) && f.severity !== 'Info');
const p4 = findings.filter(f => !p1.includes(f) && !p2.includes(f) && !p3.includes(f) && f.severity !== 'Info');
html += `<h2 class="pb">14. Action Plan</h2>` +
  phase('Phase 1 — Fix the foundations', 'Week 1', p1) +
  phase('Phase 2 — Content and on-page', 'Weeks 2-5', p2) +
  phase('Phase 3 — Authority, keywords and AI visibility (run in parallel)', 'Weeks 2-12', p3) +
  phase('Phase 4 — Polish', 'Months 2-3', p4);

// ---------- 15. Leading indicators ----------
const li = [];
li.push('SEO Health Score on the next audit (now ' + a.health_score + '/100)');
if (findings.some(f => /cache/i.test(f.title))) li.push('Homepage CDN cache status shows HIT and server response under 200ms');
li.push('Keywords in Google top 10 (now ' + num(you.top10) + ', competitor median ' + num(cb.medians && cb.medians.top10) + ')');
if (sk && (sk.easy_wins || []).length) li.push('Rankings for the easy-win keywords listed in section 4');
if (au && au.available) li.push('Referring domains (now ' + num(you.rd) + ', competitor median ' + num(au.medians && au.medians.referring_domains) + ')');
if (ps) li.push('Mobile PageSpeed score (now ' + num(you.speed) + ')');
if (av) li.push('Whether ChatGPT and Perplexity name you for category queries, and whether Google AI Overviews cite you');
li.push('Position for your brand name in Google');
html += `<h2>15. Leading Indicators to Track</h2><ul>` + li.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>';

// ---------- 16. Methodology ----------
html += `<h2 class="pb">16. Methodology & Data Sources</h2><p>${esc(a.scoring_method)}</p>
<table class="ct"><tr><th>Severity</th><th>Points deducted</th></tr><tr><td>Critical</td><td>30</td></tr><tr><td>High</td><td>15</td></tr><tr><td>Medium</td><td>7</td></tr><tr><td>Low</td><td>3</td></tr><tr><td>Info</td><td>1</td></tr></table>
<table class="ct"><tr><th>Source</th><th>Used for</th></tr>
<tr><td>DataForSEO On-Page crawl</td><td>Page-level technical and on-page checks (up to ${num(d.crawl_max_pages || 200)} pages incl. sitemap)</td></tr>
<tr><td>Direct HTTP and HTML checks</td><td>www/HTTPS, caching, headers, robots.txt, sitemap, llms.txt, schema, forms, images</td></tr>
<tr><td>DataForSEO Labs</td><td>Competitors, rankings, traffic estimates, keyword ideas by intent, keyword gap</td></tr>
<tr><td>DataForSEO Backlinks</td><td>Backlinks, referring domains, link gap</td></tr>
<tr><td>Google PageSpeed Insights</td><td>Lighthouse lab data and real-user Core Web Vitals (mobile)</td></tr>
<tr><td>Google search results (live)</td><td>Brand and category rankings, AI Overview citations, competitor discovery</td></tr>
<tr><td>AI content review (Claude)</td><td>Content quality and E-E-A-T review of sampled pages (listed, not scored)</td></tr>
<tr><td>DataForSEO LLM Responses</td><td>Live ChatGPT (web search) and Perplexity answers about the brand and category</td></tr>
<tr><td>DataForSEO On-Page reports</td><td>Duplicate titles/descriptions, non-indexable pages, redirect chains</td></tr>
<tr><td>Domain registry data</td><td>Domain registration date</td></tr></table>
${(a.not_assessed || []).length ? '<h3>Not Assessed in This Run</h3><ul>' + a.not_assessed.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : ''}
${(a.notes || []).map(n => '<p class="small">' + esc(n) + '</p>').join('')}`;

const css = `
@page { margin: 0.8in; }
body { font-family: Calibri, Arial, sans-serif; font-size: 11pt; line-height: 1.5; color: #1e293b; }
.cover { background: #0F172A; color: #fff; padding: 28px 30px; margin-bottom: 24px; }
.brand { font-size: 10pt; letter-spacing: 2px; text-transform: uppercase; color: #93C5FD; }
.title { font-size: 28pt; margin: 6px 0; color: #fff; }
.sub { color: #CBD5E1; margin: 0 0 14px; }
.scorebox td { vertical-align: middle; padding-right: 18px; color: #fff; }
.big { font-size: 44pt; font-weight: bold; }
.big span { font-size: 14pt; color: #CBD5E1; }
.grade { font-size: 16pt; font-weight: bold; color: #fff; }
.lbl { color: #93C5FD; font-size: 10pt; }
.by { color: #93C5FD; margin: 14px 0 0; font-size: 10pt; }
h2 { color: #1E3A8A; font-size: 15pt; margin-top: 26px; border-bottom: 1px solid #CBD5E1; padding-bottom: 4px; }
h3 { color: #334155; font-size: 12.5pt; margin-top: 16px; }
p { margin: 0 0 8px; }
.toc li { margin-bottom: 3px; }
.ct { width: 100%; border-collapse: collapse; margin: 10px 0; font-size: 9.5pt; }
.ct th { background: #1E3A8A; color: #fff; padding: 6px; text-align: left; }
.ct td { padding: 6px; border: 1px solid #CBD5E1; vertical-align: top; }
.ct tr.you td { background: #EEF2FF; }
.kv { width: 100%; border-collapse: collapse; margin: 10px 0 16px; }
.kv td { padding: 6px 10px; border: 1px solid #E2E8F0; font-size: 10pt; }
.kv .k { width: 240px; font-weight: bold; background: #EEF2FF; color: #0F172A; text-transform: capitalize; }
.bar { width: 100%; border-collapse: collapse; }
.bar td { height: 10px; padding: 0; border: none; font-size: 4pt; }
.good li { color: #15803D; }
.okline { color: #15803D; }
.callout { border-left: 4px solid #1E3A8A; background: #F1F5F9; padding: 10px 14px; margin: 12px 0; }
.note { border-left: 4px solid #D97706; background: #FFFBEB; padding: 10px 14px; margin: 12px 0; }
.finding { border-left: 5px solid #CBD5E1; background: #F8FAFC; padding: 10px 14px; margin: 12px 0; }
.ftitle { font-weight: bold; font-size: 11.5pt; color: #0F172A; }
.badge { color: #fff; font-size: 8pt; padding: 2px 6px; font-weight: bold; }
.fmeta { font-size: 9pt; color: #64748B; margin: 3px 0 8px; }
.small { font-size: 9pt; color: #64748B; }
.pb { page-break-before: always; }`;

const doc = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head><meta charset="utf-8"><title>Full SEO Report — ${esc(a.domain)}</title>
<!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View></w:WordDocument></xml><![endif]-->
<style>${css}</style></head><body>${html}</body></html>`;

const fileName = 'full-seo-report-' + String(a.domain).replace(/[^a-z0-9]+/gi, '-') + '-' + today + '.doc';

return [{
  json: {
    brand: d.brand || 'Dev SEO',
    report_title: 'Full SEO Report',
    domain: a.domain,
    email: d.email,
    health_score: a.health_score,
    grade: a.grade,
    issue_counts: counts,
    top_issues: top.map(f => f.title),
    file_name: fileName
  },
  binary: {
    data: {
      data: Buffer.from('\ufeff' + doc, 'utf8').toString('base64'),
      mimeType: 'application/msword',
      fileName: fileName,
      fileExtension: 'doc'
    }
  }
}];

const base = $('Schema Findings').first().json;
const pages = $('Get Crawled Pages').first().json.tasks?.[0]?.result?.[0]?.items || [];
const isHome = (u) => /^https?:\/\/[^\/]+\/?$/.test(u || '');
const skip = (u) => /privacy|cookie|terms|security|legal|contact|about|insights|blog|news|careers|whywith|whatwedo\/?$|capabilities\/?$|industries/i.test(u || '');

const cleanTitle = (t) => String(t || '')
  .split(/\s[|\-–—]\s/)[0]
  .replace(/[^\w\s&\-]/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();

const queries = [];
pages
  .filter(p => p.url && !isHome(p.url) && !skip(p.url) && (p.meta || {}).title)
  .sort((a, b) => (a.click_depth ?? 9) - (b.click_depth ?? 9))
  .forEach(p => {
    const q = cleanTitle(p.meta.title);
    if (q.split(' ').length >= 2 && !queries.includes(q)) queries.push(q);
  });

if (!queries.length) {
  const home = pages.find(p => isHome(p.url));
  const q = cleanTitle(home && home.meta && home.meta.title);
  if (q) queries.push(q);
}

const list = queries.slice(0, 3);
if (!list.length) return [{ json: { query: base.domain.split('.')[0] } }];
return list.map(q => ({ json: { query: q } }));

parameters.text:
=You are an SEO keyword strategist. Suggest the searches real buyers would type into Google to find this business.

Business: {{ $json.business || 'unknown' }}
Customers: {{ $json.audience || 'unknown' }}
Website: {{ $json.domain || 'not provided' }}
Country: {{ $json.country }}
Keywords already seen on the website: {{ JSON.stringify(($json.site_description || {}).seed_keywords || []) }}

Return ONLY a valid JSON object (no markdown, no backticks):
{
  "seeds": ["12 to 15 short search phrases, 2-5 words each, a mix of service, problem, comparison and price searches, localised for {{ $json.country }}"],
  "services": ["the main services or products this business sells"]
}

Rules:
- Use generic category terms buyers search for, not the brand name.
