// Accepts an object (from the Structured Output Parser) or a string with/without code fences or surrounding text
const parseAgentJson = (raw) => {
  if (raw && typeof raw === 'object') return raw;
  let s = String(raw || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  throw new Error('AI did not return valid JSON. Output was: ' + s.slice(0, 300));
};

const prev = $('Merge Keyword Data').first().json;
const verdict = parseAgentJson($input.first().json.output);

const allowed = ['GO', 'GO_WITH_CHANGES', 'AVOID'];
if (!allowed.includes(verdict.verdict)) verdict.verdict = 'GO_WITH_CHANGES';

return [{
  json: {
    ...prev,
    verdict: verdict.verdict,
    verdict_score: verdict.score ?? null,
    verdict_reasons: verdict.reasons || [],
    verdict_risks: verdict.risks || [],
    recommended_page: verdict.recommended_page || prev.page_type,
    secondary_keywords: verdict.secondary_keywords || []
  }
}];

const item = $input.first();
const d = item.json;
const bin = item.binary && item.binary.data ? item.binary.data : null;

return [{
  json: {
    verdict: d.verdict,
    score: d.verdict_score,
    reasons: d.verdict_reasons || [],
    risks: d.verdict_risks || [],
    recommended_page: d.recommended_page,
    secondary_keywords: d.secondary_keywords || [],
    keyword_data: d.keyword_data || null,
    existing_page: d.existing_page || null,
    qa_summary: d.qa_summary || null,
    emailed_to: d.email || null,
    callback_url: d.callback_url || '',
    keyword: d.keyword,
    domain: d.domain,
    country: d.country,
    file: bin ? {
      data: bin.data,
      fileName: bin.fileName || d.file_name,
      mimeType: bin.mimeType || 'application/msword'
    } : null
  }
}];

// Simple abuse guard: limits runs per requester and per day (state lives in workflow static data;
// it persists only for active/production executions, not manual test runs).
const LIMITS = { per_key_per_day: 6, global_per_day: 150 };

const d = $input.first().json;
const today = new Date().toISOString().slice(0, 10);
const key = (d.email || d.domain || d.keyword || 'anon').toLowerCase();

let store;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = {}; }
if (!store.rate || store.rate.day !== today) store.rate = { day: today, total: 0, keys: {} };

const used = store.rate.keys[key] || 0;
if (store.rate.total >= LIMITS.global_per_day) {
  throw new Error('This service has reached its daily capacity. Please try again tomorrow.');
}
if (used >= LIMITS.per_key_per_day) {
  throw new Error('You have reached the daily limit of ' + LIMITS.per_key_per_day + ' runs. Please try again tomorrow.');
}
store.rate.keys[key] = used + 1;
store.rate.total += 1;

return [{ json: { ...d, run_number_today: used + 1 } }];

// Single entry point for the keyword pipeline (SERP -> competitors -> brief -> content).
// Reached from Route Mode (keyword mode) or from the Discover fork (top suggested keyword).
const d = $input.first().json;
const keyword = String(d.keyword || '').trim().toLowerCase().replace(/\s+/g, ' ');
if (!keyword) throw new Error('No keyword available for the content pipeline.');
if (!d.location_code) throw new Error('No target country available for the content pipeline.');

return [{
  json: {
    ...d,
    keyword,
    page_type: d.page_type || 'Service Page',
    pipeline_source: d.pipeline_source || (d.mode === 'discover' ? 'discover' : 'form'),
    site_text: undefined,
    competitor_digest: undefined
  }
}];

// Input: the fetched /sitemap.xml (text). Output: the sitemap files to read (max 5).
const ctx = $('Prepare Keyword Run').first().json;
const r = $input.first().json || {};
const status = r.statusCode || (r.error ? 0 : 200);
const body = String(r.sitemap_xml || r.body || r.data || '');
const base = 'https://' + ctx.domain;

const locs = (body.match(/<loc>\s*([^<\s]+)\s*<\/loc>/gi) || []).map(x => x.replace(/<\/?loc>/gi, '').trim());
const isIndex = /<sitemapindex/i.test(body);

let urls = [];
if (status === 200 && isIndex && locs.length) {
  // Prefer page/post/service sitemaps over image/video/tag sitemaps
  const score = (u) => (/page|post|service|product|blog|main/i.test(u) ? 0 : 1) + (/image|video|tag|author|category|news/i.test(u) ? 2 : 0);
  urls = [...locs].sort((a, b) => score(a) - score(b)).slice(0, 5);
} else if (status === 200 && locs.length) {
  urls = [base + '/sitemap.xml'];               // plain urlset: re-read the same file in the next node
} else {
  urls = [base + '/sitemap_index.xml', base + '/wp-sitemap.xml', base + '/sitemap-index.xml', base + '/page-sitemap.xml'];
}
return urls.map(u => ({ json: { url: u } }));

// Builds the list of REAL pages on the user's site (from sitemap files) so the brief and the
// copywriter only link to URLs that exist, and detects whether a page for this keyword already exists.
const ctx = $('Prepare Keyword Run').first().json;
const bodies = ctx.domain ? $input.all().map(i => String((i.json || {}).sitemap_xml || (i.json || {}).body || '')) : [];

const STOP = new Set(['the','a','an','and','or','of','for','to','in','on','with','by','at','from','your','our','best','top','services','service','company','how','what','is','are','near','me','vs','page','pages','html','php','index','home']);
const tokens = (s) => String(s || '').toLowerCase().replace(/\.(html?|php|aspx?)$/g, '').split(/[^a-z0-9]+/).filter(t => t.length > 1 && !STOP.has(t));

const seen = new Set();
const pages = [];
for (const body of bodies) {
  if (/<sitemapindex/i.test(body) && !/<urlset/i.test(body)) continue;      // nested index, not pages
  const urlBlocks = body.match(/<url>[\s\S]*?<\/url>/gi) || [];
  const locs = urlBlocks.length
    ? urlBlocks.map(b => (b.match(/<loc>\s*([^<\s]+)\s*<\/loc>/i) || [])[1]).filter(Boolean)
    : (body.match(/<loc>\s*([^<\s]+)\s*<\/loc>/gi) || []).map(x => x.replace(/<\/?loc>/gi, '').trim());
  for (let u of locs) {
    u = u.replace(/&amp;/g, '&').trim();
    if (!/^https?:\/\//i.test(u)) continue;
    const host = u.replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#]/)[0].toLowerCase();
    if (host !== ctx.domain && !host.endsWith('.' + ctx.domain)) continue;
    if (/\.(jpe?g|png|gif|webp|svg|pdf|xml|css|js|mp4|zip)(\?|$)/i.test(u)) continue;
    const key = u.replace(/\/$/, '');
    if (seen.has(key)) continue;
    seen.add(key);
    const path = u.replace(/^https?:\/\/[^\/]+/i, '') || '/';
    pages.push({ url: u, path, tokens: tokens(path) });
    if (pages.length >= 400) break;
  }
  if (pages.length >= 400) break;
}

const kwTokens = new Set(tokens(ctx.keyword));
const overlap = (p) => p.tokens.filter(t => kwTokens.has(t)).length;
const jaccard = (p) => { const u = new Set([...p.tokens, ...kwTokens]); return u.size ? overlap(p) / u.size : 0; };

// Existing page for this keyword: explicit URL from the form, else best sitemap match
let existing_page = null;
if (ctx.existing_page_url) {
  existing_page = { url: ctx.existing_page_url, match: 1, source: 'provided' };
} else if (ctx.run_page_check || pages.length) {
  const best = pages.map(p => ({ p, j: jaccard(p), o: overlap(p) }))
    .filter(x => x.o >= Math.min(2, kwTokens.size) && x.j >= 0.5)
    .sort((a, b) => b.j - a.j)[0];
  if (best) existing_page = { url: best.p.url, match: +best.j.toFixed(2), source: 'sitemap' };
}

// Internal-link candidates: related pages first, then short hub pages
const candidates = pages
  .filter(p => p.path !== '/' && !/privacy|terms|cookie|legal|login|cart|checkout|account|search|feed|wp-|\/tag\/|\/author\//i.test(p.path))
  .map(p => ({ url: p.url, path: p.path, score: overlap(p) * 10 - p.path.split('/').filter(Boolean).length }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 40)
  .map(p => ({ url: p.url, path: p.path }));

const home = ctx.domain ? 'https://' + ctx.domain + '/' : '';

return [{
  json: {
    ...ctx,
    sitemap_ok: pages.length > 0,
    site_urls_count: pages.length,
    site_urls: pages.slice(0, 300).map(p => p.url),
    internal_link_candidates: home ? [{ url: home, path: '/' }, ...candidates] : candidates,
    existing_page
  }
}];

// Discover mode: the user also asked for a keyword report and/or page content.
// Take the best recommended keyword and run the full keyword pipeline for it.
const d = $input.first().json;
const ks = d.keyword_suggestions || {};
const pick = (ks.recommended || [])[0] || (ks.easy_wins || [])[0] || null;
if (!pick || !pick.keyword) throw new Error('No keyword with search volume was found to build content for.');

const intent = pick.intent || 'commercial';
const page_type = intent === 'informational' ? 'Blog Post' : 'Service Page';

return [{
  json: {
    ...d,
    keyword: pick.keyword,
    page_type,
    pipeline_source: 'discover',
    chosen_keyword_reason: pick.why || ('Highest-scoring ' + intent + ' keyword from the research'),
    result_html: undefined,
    file_name: undefined
  }
}];

// Extra DataForSEO On-Page reports for the finished crawl (each becomes one HTTP request)
const d = $input.first().json;
const id = d.crawl_task_id;
const base = 'https://api.dataforseo.com/v3/on_page/';
return [
  { json: { ...d, extra: 'duplicate_title',       endpoint: base + 'duplicate_tags',  body: [{ id, type: 'duplicate_title', limit: 100 }] } },
  { json: { ...d, extra: 'duplicate_description', endpoint: base + 'duplicate_tags',  body: [{ id, type: 'duplicate_description', limit: 100 }] } },
  { json: { ...d, extra: 'non_indexable',         endpoint: base + 'non_indexable',   body: [{ id, limit: 200 }] } },
  { json: { ...d, extra: 'redirect_chains',       endpoint: base + 'redirect_chains', body: [{ id, limit: 100 }] } }
];

// Consolidates the extra On-Page reports into one object. Every report is optional.
const base = $('Check Crawl').first().json;
const reqs = $('Crawl Extra Requests').all().map(i => i.json);
const res = $input.all().map(i => i.json);

const extras = { duplicate_title: [], duplicate_description: [], non_indexable: [], redirect_chains: [], errors: [] };
reqs.forEach((r, i) => {
  const j = res[i] || {};
  const task = j.tasks?.[0] || {};
  if (j.error || (task.status_code && task.status_code >= 40000)) {
    extras.errors.push(r.extra + ': ' + (task.status_message || (j.error && j.error.message) || 'failed'));
    return;
  }
  const items = task.result?.[0]?.items || [];
  if (r.extra === 'duplicate_title' || r.extra === 'duplicate_description') {
    extras[r.extra] = items.map(it => ({
      text: String(it.accumulator || it.tag || it.value || '').slice(0, 120),
      count: it.total_count ?? (it.pages || []).length,
      urls: (it.pages || []).map(p => p.url || p.page_url || p).filter(Boolean).slice(0, 5)
    })).filter(x => x.count > 1 || x.urls.length > 1);
  } else if (r.extra === 'non_indexable') {
    extras.non_indexable = items.map(it => ({ url: it.url, reason: it.reason || it.non_indexable_reason || 'unknown', status: it.status_code ?? null })).filter(x => x.url);
  } else if (r.extra === 'redirect_chains') {
    extras.redirect_chains = items.map(it => {
      const chain = it.chain || it.redirect_chain || it.items || [];
      return { start: it.url || (chain[0] && (chain[0].url || chain[0])) || '', hops: chain.length, chain: chain.map(c => c.url || c).filter(Boolean).slice(0, 6) };
    }).filter(x => x.hops >= 2);
  }
});

return [{ json: { ...base, crawl_extras: extras } }];

// Real AI-assistant answers via DataForSEO's LLM Responses API (ChatGPT with web search, Perplexity).
// Each item becomes one request to the endpoint in `endpoint` with body `body`.
const base = $('Parse Content Review').first().json;
const q = $('AI Queries').first().json;
const country = base.country || '';
const iso = base.country_iso || 'US';
const brand = q.brand_name || base.domain.split('.')[0];
const category = q.category_query || ('best ' + (base.domain.split('.')[0]) + ' alternatives');

const cut = (s, n) => String(s).slice(0, n);
const whoPrompt = cut('What is ' + brand + ' (' + base.domain + ')? What does the company do, where is it based and who is it for? Answer in 3 sentences. If you cannot find it, say exactly: I could not find this company.', 490);
const recPrompt = cut('I need to choose a provider. Which are the ' + category.replace(/\bbest\b/i, 'best').trim() + '? Give me up to 8 companies with their website domains, best first, one line each.', 490);

const items = [
  { platform: 'chat_gpt', kind: 'who', prompt: whoPrompt,
    endpoint: 'https://api.dataforseo.com/v3/ai_optimization/chat_gpt/llm_responses/live',
    body: [{ user_prompt: whoPrompt, model_name: 'gpt-4.1-mini', web_search: true, web_search_country_iso_code: iso, max_output_tokens: 400, temperature: 0.2 }] },
  { platform: 'chat_gpt', kind: 'recommend', prompt: recPrompt,
    endpoint: 'https://api.dataforseo.com/v3/ai_optimization/chat_gpt/llm_responses/live',
    body: [{ user_prompt: recPrompt, model_name: 'gpt-4.1-mini', web_search: true, web_search_country_iso_code: iso, max_output_tokens: 700, temperature: 0.2 }] },
  { platform: 'perplexity', kind: 'recommend', prompt: recPrompt,
    endpoint: 'https://api.dataforseo.com/v3/ai_optimization/perplexity/llm_responses/live',
    body: [{ user_prompt: recPrompt, model_name: 'sonar', max_output_tokens: 700, temperature: 0.2 }] }
];

return items.map(it => ({ json: { ...it, brand, category, country } }));
